     6→    <title>Tools in HTML</title>
     7→    <style>
     8→        * {
     9→            margin: 0;
    10→            padding: 0;
    11→            box-sizing: border-box;
    12→        }
    13→
    14→        body {
    15→            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    16→            background: linear-gradient(135deg, #0f0f23 0%, #1a1a3e 100%);
    17→            min-height: 100vh;
    18→            padding: 20px;
    19→            color: #fff;
    20→        }
    21→
    22→        .container {
    23→            max-width: 80%;
    24→            margin: 0 auto;
    25→        }
    26→
    27→        h1 {
    28→            text-align: center;
    29→            margin-bottom: 10px;
    30→            font-size: 2rem;
    31→            background: linear-gradient(90deg, #00d9ff, #a855f7);
    32→            -webkit-background-clip: text;
    33→            -webkit-text-fill-color: transparent;
    34→            background-clip: text;
    35→        }
    36→
    37→        .subtitle {
    38→            text-align: center;
    39→            color: #6b7280;
    40→            margin-bottom: 40px;
    41→            font-size: 14px;
    42→        }
    43→
    44→        .tools-grid {
    45→            display: grid;
    46→            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    47→            gap: 16px;
    48→            list-style: none;
    49→        }
    50→
    51→        .tool-card {
    52→            background: rgba(255, 255, 255, 0.05);
    53→            border-radius: 16px;
    54→            border: 1px solid rgba(255, 255, 255, 0.1);
    55→            transition: all 0.3s;
    56→            overflow: hidden;
    57→        }
    58→
    59→        .tool-card:hover {
    60→            background: rgba(255, 255, 255, 0.08);
    61→            transform: translateY(-4px);
    62→            box-shadow: 0 12px 24px rgba(0, 0, 0, 0.4);
    63→            border-color: rgba(0, 217, 255, 0.3);
    64→        }
    65→
    66→        .tool-card a {
    67→            display: flex;
    68→            flex-direction: column;
    69→            padding: 24px;
    70→            text-decoration: none;
    71→            height: 100%;
    72→        }
    73→
    74→        .tool-icon {
    75→            font-size: 32px;
    76→            margin-bottom: 12px;
    77→        }
    78→
    79→        .tool-name {
    80→            color: #00d9ff;
    81→            font-weight: 600;
    82→            font-size: 16px;
    83→            margin-bottom: 8px;
    84→        }
    85→
    86→        .tool-desc {
    87→            color: #9ca3af;
    88→            font-size: 13px;
    89→            line-height: 1.5;
    90→        }
    91→
    92→        @media (max-width: 640px) {
    93→            h1 {
    94→                font-size: 1.5rem;
    95→            }
    96→
    97→            .tools-grid {
    98→                grid-template-columns: 1fr;
    99→            }
   100→
   101→            .tool-card a {
   102→                padding: 20px;
   103→            }
   104→        }
   105→    </style>
   106→</head>
   107→<body>
   108→<div class="container">
   109→    <h1>Tools in HTML</h1>
   110→    <p class="subtitle">A collection of single-file browser-based tools</p>
   111→    <ul class="tools-grid">
   112→        <li class="tool-card">
   113→            <a href="base64.html">
   114→                <span class="tool-icon">🔤</span>
   115→                <span class="tool-name">Base64 Encoder/Decoder</span>
   116→                <span class="tool-desc">Encode text to Base64 or decode Base64 back to text</span>
   117→            </a>
   118→        </li>
   119→        <li class="tool-card">
   120→            <a href="countdown.html">
