   131→            </a>
   132→        </li>
   133→        <li class="tool-card">
   134→            <a href="duration.html">
   135→                <span class="tool-icon">📅</span>
   136→                <span class="tool-name">Duration Calculator</span>
   137→                <span class="tool-desc">Calculate the duration between two dates or times</span>
   138→            </a>
   139→        </li>
   140→        <li class="tool-card">
   141→            <a href="json.html">
   142→                <span class="tool-icon">📝</span>
   143→                <span class="tool-name">JSON Formatter</span>
   144→                <span class="tool-desc">Format, minify, and validate JSON data with syntax highlighting</span>
   145→            </a>
   146→        </li>
   147→        <li class="tool-card">
   148→            <a href="converter.html">
   149→                <span class="tool-icon">🔄</span>
   150→                <span class="tool-name">Format Converter</span>
   151→                <span class="tool-desc">Convert between JSON, YAML, and TOML formats</span>
   152→            </a>
   153→        </li>
   154→        <li class="tool-card">
   155→            <a href="password.html">
   156→                <span class="tool-icon">🔐</span>
   157→                <span class="tool-name">Password Generator</span>
   158→                <span class="tool-desc">Generate secure random passwords with custom options</span>
   159→            </a>
   160→        </li>
   161→        <li class="tool-card">
   162→            <a href="rsa.html">
   163→                <span class="tool-icon">🔑</span>
   164→                <span class="tool-name">RSA Private Key Parser</span>
   165→                <span class="tool-desc">Parse and inspect RSA private key details</span>
   166→            </a>
   167→        </li>
   168→        <li class="tool-card">
   169→            <a href="certificates.html">
   170→                <span class="tool-icon">📜</span>
   171→                <span class="tool-name">X.509 Certificate Parser</span>
   172→                <span class="tool-desc">Parse and display X.509 certificate information</span>
   173→            </a>
   174→        </li>
   175→        <li class="tool-card">
   176→            <a href="brewfile.html">
   177→                <span class="tool-icon">🍺</span>
   178→                <span class="tool-name">Brewfile Analyzer</span>
   179→                <span class="tool-desc">Analyze Homebrew formulas, versions, and dependencies</span>
   180→            </a>
   181→        </li>
   182→        <li class="tool-card">
   183→            <a href="image.html">
   184→                <span class="tool-icon">🐳</span>
   185→                <span class="tool-name">Container Image Analyzer</span>
   186→                <span class="tool-desc">Inspect Docker/OCI container image layers and metadata</span>
   187→            </a>
   188→        </li>
   189→        <li class="tool-card">
   190→            <a href="kubernetes.html">
   191→                <span class="tool-icon">☸️</span>
   192→                <span class="tool-name">Kubernetes Resource Analyzer</span>
   193→                <span class="tool-desc">Analyze Pod, Deployment, StatefulSet, Job specs and best practices</span>
   194→            </a>
   195→        </li>
   196→        <li class="tool-card">
   197→            <a href="calendar.html">
   198→                <span class="tool-icon">📆</span>
   199→                <span class="tool-name">Calendar</span>
   200→                <span class="tool-desc">A printable calendar with the full year on a single page</span>
   201→            </a>
   202→        </li>
   203→    </ul>
   204→</div>
   205→</body>
   206→</html>
