   205→<div class="container">
   206→    <a class="back-link" href="index.html">← Back to Tools</a>
   207→    <h1>Base64 Encoder/Decoder</h1>
   208→    <p class="subtitle">Encode and decode Base64 strings with Unicode support</p>
   209→
   210→    <div class="card">
   211→        <label for="input">Input</label>
   212→        <textarea id="input" placeholder="Enter text to encode or decode..."></textarea>
   213→    </div>
   214→
   215→    <div class="button-group">
   216→        <button class="btn-encode" onclick="encode()">Encode</button>
   217→        <button class="btn-decode" onclick="decode()">Decode</button>
   218→    </div>
   219→
   220→    <div class="swap-btn">
   221→        <button onclick="swap()" title="Swap input and output">⇅</button>
   222→    </div>
   223→
   224→    <div class="card">
   225→        <label for="output">Output</label>
   226→        <textarea id="output" placeholder="Result will be shown here..." readonly></textarea>
   227→        <div class="button-group" style="margin-bottom: 0;">
   228→            <button class="btn-copy" onclick="copyResult()">Copy</button>
   229→            <button class="btn-clear" onclick="clearAll()">Clear</button>
   230→        </div>
   231→    </div>
   232→</div>
   233→<div class="message" id="message"></div>
   234→
   235→<script>
   236→    const inputEl = document.getElementById('input');
   237→    const outputEl = document.getElementById('output');
   238→    const messageEl = document.getElementById('message');
   239→
   240→    // Auto-resize textarea
   241→    function autoResize(textarea) {
   242→        textarea.style.height = 'auto';
   243→        textarea.style.height = textarea.scrollHeight + 'px';
   244→    }
   245→
   246→    inputEl.addEventListener('input', () => autoResize(inputEl));
   247→
   248→    // Initial resize
   249→    autoResize(inputEl);
   250→    autoResize(outputEl);
   251→
   252→    function showMessage(text, type) {
   253→        messageEl.textContent = text;
   254→        messageEl.className = 'message ' + type;
   255→        setTimeout(() => {
   256→            messageEl.className = 'message';
   257→        }, 3000);
   258→    }
   259→
   260→    function encode() {
   261→        const text = inputEl.value.trim();
   262→        if (!text) {
   263→            showMessage('Please enter text to encode', 'error');
   264→            return;
   265→        }
   266→        try {
   267→            // Support Unicode characters
   268→            const bytes = new TextEncoder().encode(text);
   269→            const encoded = btoa(Array.from(bytes, b => String.fromCharCode(b)).join(''));
   270→            outputEl.value = encoded;
   271→            autoResize(outputEl);
   272→            showMessage('Encoded successfully', 'success');
   273→        } catch (e) {
   274→            showMessage('Encode failed: ' + e.message, 'error');
   275→        }
   276→    }
   277→
   278→    function decode() {
   279→        const text = inputEl.value.trim();
   280→        if (!text) {
   281→            showMessage('Please enter text to decode', 'error');
   282→            return;
   283→        }
   284→        try {
   285→            // Support Unicode characters
   286→            const bytes = Uint8Array.from(atob(text), c => c.charCodeAt(0));
   287→            const decoded = new TextDecoder().decode(bytes);
   288→            outputEl.value = decoded;
   289→            autoResize(outputEl);
   290→            showMessage('Decoded successfully', 'success');
   291→        } catch (e) {
   292→            showMessage('Decode failed: Please enter a valid Base64 string', 'error');
   293→        }
   294→    }
   295→
   296→    function swap() {
   297→        const temp = inputEl.value;
   298→        inputEl.value = outputEl.value;
   299→        outputEl.value = temp;
   300→        autoResize(inputEl);
   301→        autoResize(outputEl);
   302→    }
   303→
   304→    function copyResult() {
   305→        const text = outputEl.value;
   306→        if (!text) {
   307→            showMessage('Nothing to copy', 'error');
   308→            return;
   309→        }
   310→        navigator.clipboard.writeText(text).then(() => {
   311→            showMessage('Copied to clipboard', 'success');
   312→        }).catch(() => {
   313→            // Fallback
   314→            outputEl.select();
   315→            document.execCommand('copy');
   316→            showMessage('Copied to clipboard', 'success');
   317→        });
   318→    }
   319→
   320→    function clearAll() {
   321→        inputEl.value = '';
   322→        outputEl.value = '';
   323→        autoResize(inputEl);
   324→        autoResize(outputEl);
   325→        showMessage('Cleared', 'success');
   326→    }
   327→</script>
   328→</body>
