   516→    <script src="https://cdn.jsdelivr.net/npm/flatpickr/dist/plugins/confirmDate/confirmDate.js"></script>
   517→    <script>
   518→        const targetEl = document.getElementById('target');
   519→        const nameEl = document.getElementById('name');
   520→        const resultCardEl = document.getElementById('resultCard');
   521→        const resultTitleEl = document.getElementById('resultTitle');
   522→        const resultValueEl = document.getElementById('resultValue');
   523→        const messageEl = document.getElementById('message');
   524→
   525→        let intervalId = null;
   526→        let targetPicker;
   527→
   528→        // Initialize Flatpickr
   529→        const flatpickrConfig = {
   530→            enableTime: true,
   531→            dateFormat: "Y-m-d H:i",
   532→            time_24hr: true,
   533→            allowInput: true,
   534→            disableMobile: true,
   535→            plugins: [new confirmDatePlugin({})]
   536→        };
   537→
   538→        // Default target: tomorrow same time
   539→        const tomorrow = new Date();
   540→        tomorrow.setDate(tomorrow.getDate() + 1);
   541→        tomorrow.setSeconds(0, 0);
   542→
   543→        targetPicker = flatpickr(targetEl, {
   544→            ...flatpickrConfig,
   545→            defaultDate: tomorrow,
   546→            onChange: (selectedDates) => {
   547→                if (selectedDates.length > 0) {
   548→                    selectedDates[0].setSeconds(0, 0);
   549→                }
   550→            }
   551→        });
   552→
   553→        function showMessage(text, type) {
   554→            messageEl.textContent = text;
   555→            messageEl.className = 'message ' + type;
   556→            setTimeout(() => {
   557→                messageEl.className = 'message';
   558→            }, 3000);
   559→        }
   560→
   561→        // Clear hash when user modifies time
   562→        function clearHash() {
   563→            if (window.location.hash) {
   564→                history.replaceState(null, null, window.location.pathname);
   565→            }
   566→        }
   567→
   568→        // Listen for Flatpickr changes
   569→        targetEl.addEventListener('change', () => {
   570→            updateShareButton();
   571→            clearHash();
   572→        });
   573→
   574→        function startCountdown() {
   575→            const targetDate = targetPicker.selectedDates[0];
   576→            if (!targetDate) {
   577→                showMessage('Please enter a target time', 'error');
   578→                return;
   579→            }
   580→
   581→            // Clear existing interval
   582→            if (intervalId) {
   583→                clearInterval(intervalId);
   584→            }
   585→
   586→            updateDisplay();
   587→            intervalId = setInterval(updateDisplay, 1000);
   588→        }
   589→
   590→        function updateDisplay() {
   591→            const targetDate = targetPicker.selectedDates[0];
   592→            if (!targetDate) return;
   593→
   594→            const now = new Date();
   595→            const diff = targetDate - now;
   596→            const isExpired = diff <= 0;
   597→            const absDiff = Math.abs(diff);
   598→
   599→            const days = Math.floor(absDiff / (1000 * 60 * 60 * 24));
   600→            const hours = Math.floor((absDiff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
   601→            const minutes = Math.floor((absDiff % (1000 * 60 * 60)) / (1000 * 60));
   602→            const seconds = Math.floor((absDiff % (1000 * 60)) / 1000);
   603→
   604→            // Format main display
   605→            let parts = [];
   606→            if (days > 0) parts.push(days + 'd');
   607→            if (hours > 0 || days > 0) parts.push(hours + 'h');
   608→            if (minutes > 0 || hours > 0 || days > 0) parts.push(minutes + 'm');
   609→            parts.push(seconds + 's');
   610→
   611→            let displayValue;
   612→            if (isExpired) {
   613→                displayValue = 'EXPIRED';
   614→            } else {
   615→                displayValue = parts.join(' ');
   616→            }
   617→
   618→            // Update UI
   619→            resultCardEl.style.display = 'block';
   620→            resultValueEl.textContent = displayValue;
   621→            resultValueEl.className = 'result-value' + (isExpired ? ' expired' : '');
   622→
   623→            const daysEl = document.getElementById('days');
   624→            const hoursEl = document.getElementById('hours');
   625→            const minutesEl = document.getElementById('minutes');
   626→            const secondsEl = document.getElementById('seconds');
   627→
   628→            daysEl.textContent = days;
   629→            hoursEl.textContent = hours;
   630→            minutesEl.textContent = minutes;
   631→            secondsEl.textContent = seconds;
   632→
   633→            // Update total seconds
   634→            const totalSeconds = Math.floor(absDiff / 1000);
   635→            const totalSecondsEl = document.getElementById('totalSeconds');
   636→            if (isExpired) {
   637→                totalSecondsEl.textContent = `Expired: ${totalSeconds.toLocaleString()} seconds`;
   638→            } else {
   639→                totalSecondsEl.textContent = `Total: ${totalSeconds.toLocaleString()} seconds`;
   640→            }
   641→
   642→            // Update title
   643→            const name = nameEl.value.trim();
   644→            let titleText = name || 'Countdown';
   645→
   646→            const badgeClass = isExpired ? 'live-badge expired' : 'live-badge';
   647→            const badgeText = isExpired ? 'EXPIRED' : 'LIVE';
   648→
   649→            // Set title text safely
   650→            resultTitleEl.textContent = titleText;
   651→
   652→            // Create and append badge element
   653→            const badge = document.createElement('span');
   654→            badge.className = badgeClass;
   655→            badge.textContent = badgeText;
   656→            resultTitleEl.appendChild(badge);
   657→        }
   658→
   659→        function clearAll() {
   660→            if (intervalId) {
   661→                clearInterval(intervalId);
   662→                intervalId = null;
   663→            }
   664→
   665→            targetPicker.clear();
   666→            targetEl.value = '';
   667→            nameEl.value = '';
   668→            resultCardEl.style.display = 'none';
   669→            messageEl.className = 'message';
   670→            clearHash();
   671→            updateShareButton();
   672→
   673→            // Reset default target
   674→            const tomorrow = new Date();
   675→            tomorrow.setDate(tomorrow.getDate() + 1);
   676→            tomorrow.setSeconds(0, 0);
   677→            targetPicker.setDate(tomorrow);
   678→        }
