   680→        // Base62 charset
   681→        const BASE62 = 'REDACTED';
   682→
   683→        // Encode number to Base62
   684→        function encodeBase62(num) {
   685→            if (num === 0n) return '0';
   686→            let arr = [];
   687→            while (num > 0n) {
   688→                arr.push(BASE62[Number(num % 62n)]);
   689→                num = num / 62n;
   690→            }
   691→            return arr.reverse().join('');
   692→        }
   693→
   694→        // Decode Base62 to number
   695→        function decodeBase62(str) {
   696→            let num = 0n;
   697→            for (let i = 0; i < str.length; i++) {
   698→                const idx = BASE62.indexOf(str[i]);
   699→                if (idx === -1) throw new Error('Invalid character');
   700→                num = num * 62n + BigInt(idx);
   701→            }
   702→            return num;
   703→        }
   704→
   705→        // Base64URL encode (URL-safe, no padding)
   706→        function encodeBase64URL(str) {
   707→            const bytes = new TextEncoder().encode(str);
   708→            let binary = '';
   709→            bytes.forEach(b => binary += String.fromCharCode(b));
   710→            return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
   711→        }
   712→
   713→        // Base64URL decode
   714→        function decodeBase64URL(str) {
   715→            str = str.replace(/-/g, '+').replace(/_/g, '/');
   716→            while (str.length % 4) str += '=';
   717→            const binary = atob(str);
   718→            const bytes = new Uint8Array(binary.length);
   719→            for (let i = 0; i < binary.length; i++) {
   720→                bytes[i] = binary.charCodeAt(i);
   721→            }
   722→            return new TextDecoder().decode(bytes);
   723→        }
   724→
   725→        // Share URL function
   726→        function shareUrl() {
   727→            const targetDate = targetPicker.selectedDates[0];
   728→            if (!targetDate) {
   729→                showMessage('Please set target time', 'error');
   730→                return;
   731→            }
   732→
   733→            const targetTs = Math.floor(targetDate.getTime() / 1000);
   734→            const timeHash = encodeBase62(BigInt(targetTs));
   735→            const name = nameEl.value.trim();
   736→
   737→            // Format: #s={base62} or #s={base62}.{base64url_name}
   738→            let hash = timeHash;
   739→            if (name) {
   740→                hash += '.' + encodeBase64URL(name);
   741→            }
   742→
   743→            const url = window.location.origin + window.location.pathname + '#s=' + hash;
   744→
   745→            // Update current URL
   746→            history.pushState(null, null, '#s=' + hash);
   747→
   748→            navigator.clipboard.writeText(url).then(() => {
   749→                showMessage('Share link copied to clipboard!', 'success');
   750→            }).catch(() => {
   751→                showMessage('Failed to copy link', 'error');
   752→            });
   753→        }
   754→
   755→        // Update share button state
   756→        function updateShareButton() {
   757→            const shareBtn = document.getElementById('shareBtn');
   758→            const hasTarget = targetPicker.selectedDates.length > 0;
   759→            shareBtn.disabled = !hasTarget;
   760→        }
   761→
   762→        // Parse hash on page load
   763→        function parseHash() {
   764→            const hash = window.location.hash;
   765→            if (hash && hash.startsWith('#s=')) {
   766→                const hashContent = hash.substring(3);
   767→
   768→                // Check if there's a name: format is {base62}.{base64url_name}
   769→                const dotIndex = hashContent.indexOf('.');
   770→                let timeHash, name = '';
   771→
   772→                if (dotIndex !== -1) {
   773→                    timeHash = hashContent.substring(0, dotIndex);
   774→                    try {
   775→                        name = decodeBase64URL(hashContent.substring(dotIndex + 1));
   776→                    } catch (e) {
   777→                        // Invalid name encoding, ignore
   778→                    }
   779→                } else {
   780→                    timeHash = hashContent;
   781→                }
   782→
   783→                try {
   784→                    const targetTs = Number(decodeBase62(timeHash));
   785→                    const targetDate = new Date(targetTs * 1000);
   786→                    targetDate.setSeconds(0, 0);
   787→                    targetPicker.setDate(targetDate);
   788→
   789→                    if (name) {
   790→                        nameEl.value = name;
   791→                    }
   792→
   793→                    // Auto start countdown
   794→                    startCountdown();
   795→                } catch (e) {
   796→                    // Invalid hash, ignore
   797→                }
   798→            }
   799→        }
   800→
   801→        // Parse hash on load
   802→        parseHash();
   803→
   804→        // Update share button state on init
   805→        updateShareButton();
   806→    </script>
