   382→                <label for="text1">Original Text</label>
   383→                <div class="editor-container">
   384→                    <div class="line-numbers" id="lineNumbers1">
   385→                        <div>1</div>
   386→                    </div>
   387→                    <textarea id="text1" placeholder="Enter original text..."></textarea>
   388→                </div>
   389→            </div>
   390→            <div class="input-section">
   391→                <label for="text2">Modified Text</label>
   392→                <div class="editor-container">
   393→                    <div class="line-numbers" id="lineNumbers2">
   394→                        <div>1</div>
   395→                    </div>
   396→                    <textarea id="text2" placeholder="Enter modified text..."></textarea>
   397→                </div>
   398→            </div>
