   400→
   401→        <div class="button-group">
   402→            <button class="btn-compare" onclick="compare()">Compare</button>
   403→            <button class="btn-swap" onclick="swap()">Swap</button>
   404→            <button class="btn-clear" onclick="clearAll()">Clear</button>
   405→        </div>
