   407→
   408→    <div class="result-section" id="result">
   409→        <div class="card">
   410→            <div class="card-title">Diff Result</div>
   411→
   412→            <div class="mode-toggle">
   413→                <button class="mode-btn active" id="modeLineBtn" onclick="setMode('line')">Line by Line</button>
   414→                <button class="mode-btn" id="modeCharBtn" onclick="setMode('char')">Character</button>
   415→            </div>
   416→
   417→            <div class="stats" id="stats"></div>
   418→            <div class="diff-output" id="diffOutput"></div>
   419→        </div>
   420→    </div>
   421→</div>
   422→
   423→<script>
   424→    const text1El = document.getElementById('text1');
   425→    const text2El = document.getElementById('text2');
   426→    const resultEl = document.getElementById('result');
   427→    const diffOutputEl = document.getElementById('diffOutput');
   428→    const statsEl = document.getElementById('stats');
   429→    const lineNumbers1 = document.getElementById('lineNumbers1');
   430→    const lineNumbers2 = document.getElementById('lineNumbers2');
   431→
   432→    let currentMode = 'line';
   433→
   434→    // Update line numbers for a textarea
   435→    function updateLineNumbers(textarea, lineNumbersEl) {
   436→        const lines = textarea.value.split('\n');
   437→        const count = lines.length;
   438→        let html = '';
   439→        for (let i = 1; i <= count; i++) {
   440→            html += `<div>${i}</div>`;
   441→        }
   442→        lineNumbersEl.innerHTML = html;
   443→    }
   444→
   445→    // Sync scroll between textarea and line numbers
   446→    function syncScroll(textarea, lineNumbersEl) {
   447→        lineNumbersEl.scrollTop = textarea.scrollTop;
   448→    }
   449→
   450→    // Initialize line numbers and event listeners
   451→    function initEditor(textarea, lineNumbersEl) {
   452→        updateLineNumbers(textarea, lineNumbersEl);
   453→        textarea.addEventListener('input', () => {
   454→            autoResize(textarea);
   455→            updateLineNumbers(textarea, lineNumbersEl);
   456→        });
   457→        textarea.addEventListener('scroll', () => syncScroll(textarea, lineNumbersEl));
   458→        // Initial resize
   459→        autoResize(textarea);
   460→    }
   461→
   462→    // Auto-resize textarea
   463→    function autoResize(textarea) {
   464→        textarea.style.height = 'auto';
   465→        textarea.style.height = textarea.scrollHeight + 'px';
   466→    }
   467→
   468→    initEditor(text1El, lineNumbers1);
   469→    initEditor(text2El, lineNumbers2);
   470→    let lastText1 = '';
   471→    let lastText2 = '';
   472→
   473→    function setMode(mode) {
   474→        currentMode = mode;
   475→        document.getElementById('modeLineBtn').classList.toggle('active', mode === 'line');
   476→        document.getElementById('modeCharBtn').classList.toggle('active', mode === 'char');
   477→        if (lastText1 || lastText2) {
   478→            displayDiff(lastText1, lastText2);
   479→        }
   480→    }
   481→
   482→    // Longest Common Subsequence for diff
   483→    function lcs(a, b) {
   484→        const m = a.length;
   485→        const n = b.length;
   486→        const dp = Array(m + 1).fill(null).map(() => Array(n + 1).fill(0));
   487→
   488→        for (let i = 1; i <= m; i++) {
   489→            for (let j = 1; j <= n; j++) {
   490→                if (a[i - 1] === b[j - 1]) {
   491→                    dp[i][j] = dp[i - 1][j - 1] + 1;
   492→                } else {
   493→                    dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
   494→                }
   495→            }
   496→        }
   497→
   498→        // Backtrack to find diff
   499→        const diff = [];
   500→        let i = m, j = n;
   501→        while (i > 0 || j > 0) {
   502→            if (i > 0 && j > 0 && a[i - 1] === b[j - 1]) {
   503→                diff.unshift({type: 'unchanged', value: a[i - 1]});
   504→                i--;
   505→                j--;
   506→            } else if (j > 0 && (i === 0 || dp[i][j - 1] >= dp[i - 1][j])) {
   507→                diff.unshift({type: 'added', value: b[j - 1]});
   508→                j--;
   509→            } else {
   510→                diff.unshift({type: 'removed', value: a[i - 1]});
   511→                i--;
   512→            }
   513→        }
   514→
   515→        return diff;
   516→    }
   517→
   518→    const MAX_LINES_WARNING = 5000;
   519→    const MAX_CHARS_WARNING = 100000;
   520→
   521→    function compare() {
   522→        const t1 = text1El.value;
   523→        const t2 = text2El.value;
   524→
   525→        if (!t1 && !t2) {
   526→            return;
   527→        }
   528→
   529→        // Performance warning for large texts
   530→        const lines1 = t1.split('\n').length;
   531→        const lines2 = t2.split('\n').length;
   532→        const totalChars = t1.length + t2.length;
   533→
   534→        if (lines1 > MAX_LINES_WARNING || lines2 > MAX_LINES_WARNING || totalChars > MAX_CHARS_WARNING) {
   535→            if (!confirm(`Warning: Large text detected (${Math.max(lines1, lines2)} lines, ${totalChars} characters). This may cause the browser to slow down. Continue?`)) {
   536→                return;
   537→            }
   538→        }
   539→
   540→        lastText1 = t1;
   541→        lastText2 = t2;
   542→
   543→        resultEl.classList.add('show');
   544→        displayDiff(t1, t2);
   545→    }
   546→
   547→    function displayDiff(t1, t2) {
   548→        if (t1 === t2) {
   549→            statsEl.innerHTML = '';
   550→            diffOutputEl.innerHTML = '<div class="identical-message">Texts are identical</div>';
   551→            return;
   552→        }
   553→
   554→        if (currentMode === 'line') {
   555→            displayLineDiff(t1, t2);
   556→        } else {
   557→            displayCharDiff(t1, t2);
   558→        }
   559→    }
   560→
   561→    function displayLineDiff(t1, t2) {
   562→        // Normalize: remove trailing empty line from split result if text doesn't end with newline
   563→        const lines1 = t1.split('\n');
   564→        const lines2 = t2.split('\n');
   565→
   566→        // Track if texts end with newline
   567→        const t1EndsWithNewline = t1.endsWith('\n');
   568→        const t2EndsWithNewline = t2.endsWith('\n');
   569→
   570→        // Remove the trailing empty string that split creates for trailing newlines
   571→        // We'll handle newline endings separately
   572→        if (t1EndsWithNewline && lines1[lines1.length - 1] === '') lines1.pop();
   573→        if (t2EndsWithNewline && lines2[lines2.length - 1] === '') lines2.pop();
   574→
   575→        const diff = lcs(lines1, lines2);
   576→
   577→        let added = 0, removed = 0, unchanged = 0;
   578→        let html = '';
   579→        let lineNum1 = 1, lineNum2 = 1;
   580→
   581→        diff.forEach(item => {
   582→            const escaped = escapeHtml(item.value);
   583→            const displayValue = escaped === '' ? '<span style="opacity:0.5;font-style:italic">(empty line)</span>' : escaped;
   584→
   585→            if (item.type === 'added') {
   586→                html += `<div class="diff-line added"><span class="line-num">+${lineNum2}</span>${displayValue}</div>`;
   587→                lineNum2++;
   588→                added++;
   589→            } else if (item.type === 'removed') {
   590→                html += `<div class="diff-line removed"><span class="line-num">-${lineNum1}</span>${displayValue}</div>`;
   591→                lineNum1++;
   592→                removed++;
   593→            } else {
   594→                html += `<div class="diff-line unchanged"><span class="line-num">${lineNum1}</span>${displayValue}</div>`;
   595→                lineNum1++;
   596→                lineNum2++;
   597→                unchanged++;
   598→            }
   599→        });
   600→
   601→        // Show trailing newline difference
   602→        if (t1EndsWithNewline !== t2EndsWithNewline) {
   603→            if (t1EndsWithNewline && !t2EndsWithNewline) {
   604→                html += `<div class="diff-line removed"><span class="line-num">-</span><span style="opacity:0.7;font-style:italic">⏎ (trailing newline)</span></div>`;
   605→                removed++;
   606→            } else {
   607→                html += `<div class="diff-line added"><span class="line-num">+</span><span style="opacity:0.7;font-style:italic">⏎ (trailing newline)</span></div>`;
   608→                added++;
   609→            }
   610→        }
   611→
   612→        statsEl.innerHTML = `
   613→                <div class="stat-item added">
   614→                    <div>
   615→                        <div class="stat-value" style="color: #10b981">${added}</div>
   616→                        <div class="stat-label">Added</div>
   617→                    </div>
   618→                </div>
   619→                <div class="stat-item removed">
   620→                    <div>
   621→                        <div class="stat-value" style="color: #ef4444">${removed}</div>
   622→                        <div class="stat-label">Removed</div>
   623→                    </div>
   624→                </div>
   625→                <div class="stat-item unchanged">
   626→                    <div>
   627→                        <div class="stat-value" style="color: #9ca3af">${unchanged}</div>
   628→                        <div class="stat-label">Unchanged</div>
   629→                    </div>
   630→                </div>
   631→            `;
   632→
   633→        diffOutputEl.innerHTML = html;
   634→    }
   635→
   636→    function displayCharDiff(t1, t2) {
   637→        const chars1 = t1.split('');
   638→        const chars2 = t2.split('');
   639→        const diff = lcs(chars1, chars2);
   640→
   641→        let added = 0, removed = 0;
   642→        let lineNum = 1;
   643→        let html = '<div class="char-diff-container">';
   644→        html += `<span class="char-line-num">${lineNum}</span>`;
   645→
   646→        diff.forEach(item => {
   647→            const escaped = escapeHtml(item.value);
   648→
   649→            if (item.type === 'added') {
   650→                if (item.value === '\n') {
   651→                    html += `<span class="char-added char-newline">↵</span><br>`;
   652→                    lineNum++;
   653→                    html += `<span class="char-line-num">${lineNum}</span>`;
   654→                } else if (item.value === ' ') {
   655→                    html += `<span class="char-added char-space">·</span>`;
   656→                } else if (item.value === '\t') {
   657→                    html += `<span class="char-added char-tab">→</span>`;
   658→                } else {
   659→                    html += `<span class="char-added">${escaped}</span>`;
   660→                }
   661→                added++;
   662→            } else if (item.type === 'removed') {
   663→                if (item.value === '\n') {
   664→                    html += `<span class="char-removed char-newline">↵</span>`;
   665→                } else if (item.value === ' ') {
   666→                    html += `<span class="char-removed char-space">·</span>`;
   667→                } else if (item.value === '\t') {
   668→                    html += `<span class="char-removed char-tab">→</span>`;
   669→                } else {
   670→                    html += `<span class="char-removed">${escaped}</span>`;
   671→                }
   672→                removed++;
   673→            } else {
   674→                if (item.value === '\n') {
   675→                    html += '<br>';
   676→                    lineNum++;
   677→                    html += `<span class="char-line-num">${lineNum}</span>`;
   678→                } else {
   679→                    html += escaped;
   680→                }
   681→            }
   682→        });
   683→
   684→        html += '</div>';
   685→
   686→        statsEl.innerHTML = `
   687→                <div class="stat-item added">
   688→                    <div>
   689→                        <div class="stat-value" style="color: #10b981">${added}</div>
   690→                        <div class="stat-label">Characters Added</div>
   691→                    </div>
   692→                </div>
   693→                <div class="stat-item removed">
   694→                    <div>
   695→                        <div class="stat-value" style="color: #ef4444">${removed}</div>
   696→                        <div class="stat-label">Characters Removed</div>
   697→                    </div>
   698→                </div>
   699→            `;
   700→
   701→        diffOutputEl.innerHTML = html;
   702→    }
   703→
   704→    function escapeHtml(text) {
   705→        const div = document.createElement('div');
   706→        div.textContent = text;
   707→        return div.innerHTML;
   708→    }
   709→
   710→    function swap() {
   711→        const temp = text1El.value;
   712→        text1El.value = text2El.value;
   713→        text2El.value = temp;
   714→        updateLineNumbers(text1El, lineNumbers1);
   715→        updateLineNumbers(text2El, lineNumbers2);
   716→        autoResize(text1El);
   717→        autoResize(text2El);
   718→    }
   719→
   720→    function clearAll() {
   721→        text1El.value = '';
   722→        text2El.value = '';
   723→        resultEl.classList.remove('show');
   724→        lastText1 = '';
   725→        lastText2 = '';
   726→        updateLineNumbers(text1El, lineNumbers1);
   727→        updateLineNumbers(text2El, lineNumbers2);
   728→        autoResize(text1El);
   729→        autoResize(text2El);
   730→    }
   731→</script>
