   298→<body>
   299→<div class="container">
   300→    <a class="back-link" href="index.html">← Back to Tools</a>
   301→    <h1>JSON Formatter</h1>
   302→    <p class="subtitle">Format, minify, and validate JSON data</p>
   303→
   304→    <div class="card">
   305→        <div class="card-header">
   306→            <label>Input</label>
   307→            <button class="btn-clear-small" onclick="clearAll()">Clear</button>
   308→        </div>
   309→        <div id="editor-wrapper">
   310→            <textarea id="input" hidden></textarea>
   311→        </div>
   312→    </div>
   313→
   314→    <div class="card">
   315→        <div class="card-header">
   316→            <div style="display: flex; align-items: center;">
   317→                <label>Output</label>
   318→                <span class="format-buttons">
   319→                    <button class="format-btn" onclick="formatJSON(2)">2 spaces</button>
   320→                    <button class="format-btn" onclick="formatJSON(4)">4 spaces</button>
   321→                    <button class="format-btn minify" onclick="minifyJSON()">Minify</button>
   322→                </span>
   323→            </div>
   324→            <button class="btn-copy-small" onclick="copyResult()">Copy</button>
   325→        </div>
   326→        <div id="output-wrapper">
   327→            <textarea id="output" hidden></textarea>
   328→        </div>
