   333→<script defer src="https://cdn.jsdelivr.net/npm/codemirror@5.65.16/lib/codemirror.min.js"></script>
   334→<script defer src="https://cdn.jsdelivr.net/npm/codemirror@5.65.16/mode/javascript/javascript.min.js"></script>
   335→<script defer src="https://cdn.jsdelivr.net/npm/codemirror@5.65.16/addon/edit/matchbrackets.min.js"></script>
   336→<script defer src="https://cdn.jsdelivr.net/npm/codemirror@5.65.16/addon/edit/closebrackets.min.js"></script>
   337→<script defer src="https://cdn.jsdelivr.net/npm/codemirror@5.65.16/addon/fold/foldcode.min.js"></script>
   338→<script defer src="https://cdn.jsdelivr.net/npm/codemirror@5.65.16/addon/fold/foldgutter.min.js"></script>
   339→<script defer src="https://cdn.jsdelivr.net/npm/codemirror@5.65.16/addon/fold/brace-fold.min.js"></script>
   340→<script defer src="https://cdn.jsdelivr.net/npm/codemirror-addon-indent-guide@1.0.1/dist/indent-guide.js"></script>
   341→
   342→<script type="module">
   343→    const inputEl = document.getElementById('input');
   344→    const outputEl = document.getElementById('output');
   345→    const messageEl = document.getElementById('message');
   346→
   347→    // 共享的 CodeMirror 配置
   348→    const baseConfig = {
   349→        mode: "application/json",
   350→        theme: "material-darker",
   351→        lineNumbers: true,
   352→        lineWrapping: true,
   353→        viewportMargin: Infinity,  // 配合 height:auto 使用，渲染所有行
   354→        matchBrackets: true,
   355→        autoCloseBrackets: true,
   356→        indentUnit: 2,
   357→        tabSize: 2,
   358→        indentGuide: true,
   359→        foldGutter: {
   360→            rangeFinder: CodeMirror.fold.brace
   361→        },
   362→        gutters: ["CodeMirror-linenumbers", "CodeMirror-foldgutter"],
   363→        extraKeys: {
   364→            "Ctrl-Q": function(cm) { cm.foldCode(cm.getCursor(), CodeMirror.fold.brace); }
   365→        }
   366→    };
   367→
   368→    // 初始化 CodeMirror 编辑器（输入框）
   369→    const editor = CodeMirror.fromTextArea(inputEl, baseConfig);
   370→
   371→    // 初始化 CodeMirror 编辑器（输出框，只读）
   372→    const editorOutput = CodeMirror.fromTextArea(outputEl, {
   373→        ...baseConfig,
   374→        readOnly: true
   375→    });
   376→
   377→    // 强制更新编辑器
   378→    setTimeout(() => {
   379→        editor.refresh();
   380→        editorOutput.refresh();
   381→    }, 100);
   382→
   383→    function showMessage(text, type) {
   384→        messageEl.textContent = text;
   385→        messageEl.className = 'message ' + type;
   386→        setTimeout(() => {
   387→            messageEl.className = 'message';
   388→        }, 3000);
   389→    }
   390→
   391→    function validateInput(operation) {
   392→        const text = editor.getValue().trim();
   393→        if (!text) {
   394→            showMessage(`Please enter JSON to ${operation}`, 'error');
   395→            return null;
   396→        }
   397→        return text;
   398→    }
   399→
   400→    function tryParseJSON(text) {
   401→        let firstError;
   402→        try {
   403→            return JSON.parse(text);
   404→        } catch (e) {
   405→            firstError = e;
   406→        }
   407→
   408→        // Try unescaping key/value quotes only (common when copying from logs/code).
   409→        // Avoid touching \\\" inside string content.
   410→        if (!text.includes('\\"')) {
   411→            throw firstError;
   412→        }
   413→
   414→        const unescaped = text.replace(/(?<!\\)\\"/g, '"');
   415→        if (unescaped === text) {
   416→            throw firstError;
   417→        }
   418→
   419→        try {
   420→            return JSON.parse(unescaped);
   421→        } catch (_) {
   422→            throw firstError;
   423→        }
   424→    }
   425→
   426→    function processJSON(text, processor, successMessage) {
   427→        try {
   428→            const parsed = tryParseJSON(text);
   429→            const result = processor(parsed);
   430→            editorOutput.setValue(result);
   431→            editorOutput.clearHistory();
   432→            editorOutput.refresh();
   433→            showMessage(successMessage, 'success');
   434→            return true;
   435→        } catch (e) {
   436→            showMessage('Invalid JSON: ' + e.message, 'error');
   437→            return false;
   438→        }
   439→    }
   440→
   441→    window.formatJSON = function(indent) {
   442→        const text = validateInput('format');
   443→        if (!text) return;
   444→
   445→        editorOutput.setOption('indentUnit', indent);
   446→        processJSON(text, (parsed) => {
   447→            return JSON.stringify(parsed, null, indent);
   448→        }, 'Formatted successfully');
   449→    };
   450→
   451→    window.minifyJSON = function() {
   452→        const text = validateInput('minify');
   453→        if (!text) return;
   454→
   455→        processJSON(text, (parsed) => {
   456→            return JSON.stringify(parsed);
   457→        }, 'Minified successfully');
   458→    };
   459→
   460→    window.copyResult = function() {
   461→        const text = editorOutput.getValue();
   462→        if (!text) {
   463→            showMessage('Nothing to copy', 'error');
   464→            return;
   465→        }
   466→        navigator.clipboard.writeText(text).then(() => {
   467→            showMessage('Copied to clipboard', 'success');
   468→        }).catch(() => {
   469→            showMessage('Failed to copy', 'error');
   470→        });
   471→    };
   472→
   473→    window.clearAll = function() {
   474→        editor.setValue('');
   475→        editor.clearHistory();
   476→        editorOutput.setValue('');
   477→        editorOutput.clearHistory();
   478→        showMessage('Cleared', 'success');
   479→    };
   480→</script>
