   383→<script type="module">
   384→    // Load TOML library asynchronously
   385→    let TOML = null;
   386→    const tomlReady = import('https://cdn.jsdelivr.net/npm/smol-toml@1.3.1/+esm').then(m => {
   387→        TOML = m.default;
   388→    }).catch(err => {
   389→        console.warn('TOML library failed to load:', err);
   390→    });
   391→
   392→    const inputEl = document.getElementById('input');
   393→    const outputEl = document.getElementById('output');
   394→    const messageEl = document.getElementById('message');
   395→    const formatBadge = document.getElementById('detected-format');
   396→    
   397→    let inputFormat = 'json';
   398→    let outputFormat = null;
   399→
   400→    const modeMap = {
   401→        json: 'application/json',
   402→        yaml: 'yaml',
   403→        toml: 'toml'
   404→    };
   405→
   406→    const baseConfig = {
   407→        theme: "material-darker",
   408→        lineNumbers: true,
   409→        lineWrapping: true,
   410→        viewportMargin: Infinity,  // 配合 height:auto 使用，渲染所有行
   411→        maxHighlightLength: Infinity,  // 禁用高亮长度限制
   412→        matchBrackets: true,
   413→        autoCloseBrackets: true,
   414→        indentUnit: 2,
   415→        tabSize: 2,
   416→        indentGuide: true,
   417→        foldGutter: {
   418→            rangeFinder: CodeMirror.fold.auto
   419→        },
   420→        gutters: ["CodeMirror-linenumbers", "CodeMirror-foldgutter"],
   421→        extraKeys: {
   422→            "Ctrl-Q": function(cm) { cm.foldCode(cm.getCursor()); }
   423→        }
   424→    };
   425→
   426→    const editor = CodeMirror.fromTextArea(inputEl, {
   427→        ...baseConfig,
   428→        mode: modeMap[inputFormat]
   429→    });
   430→
   431→    const editorOutput = CodeMirror.fromTextArea(outputEl, {
   432→        ...baseConfig,
   433→        mode: null,
   434→        readOnly: true
   435→    });
   436→
   437→    // Hide loading overlay and refresh editors
   438→    requestAnimationFrame(() => {
   439→        editor.refresh();
   440→        editorOutput.refresh();
   441→        document.getElementById('loading').classList.add('hidden');
   442→    });
   443→
   444→    function detectFormat(text) {
   445→        text = text.trim();
   446→        if (!text) return null;
   447→
   448→        // 1. JSON (strictest) - must start with { or [
   449→        if (text.startsWith('{') || text.startsWith('[')) {
   450→            try {
   451→                const result = JSON.parse(text);
   452→                if (typeof result === 'object' && result !== null) {
   453→                    return 'json';
   454→                }
   455→            } catch (e) {}
   456→        }
   457→
   458→        // 2. TOML (stricter than YAML) - only if library is loaded
   459→        if (TOML) {
   460→            try {
   461→                const result = TOML.parse(text);
   462→                if (typeof result === 'object' && Object.keys(result).length > 0) {
   463→                    return 'toml';
   464→                }
   465→            } catch (e) {}
   466→        }
   467→
   468→        // 3. YAML (most lenient, fallback)
   469→        try {
   470→            const result = jsyaml.load(text);
   471→            if (typeof result === 'object' && result !== null) {
   472→                return 'yaml';
   473→            }
   474→        } catch (e) {}
   475→
   476→        return null;
   477→    }
   478→
   479→    let debounceTimeout;
   480→
   481→    function debouncedDetectAndConvert(immediate = false) {
   482→        const text = editor.getValue();
   483→
   484→        clearTimeout(debounceTimeout);
   485→
   486→        if (immediate) {
   487→            // Immediate detection for paste events
   488→            const detected = detectFormat(text);
   489→            if (detected) {
   490→                window.setInputFormat(detected);
   491→            }
   492→            // Only convert if output format is selected
   493→            if (outputFormat && text.trim()) {
   494→                window.convert();
   495→            }
   496→        } else {
   497→            // Debounced detection
   498→            debounceTimeout = setTimeout(() => {
   499→                const detected = detectFormat(text);
   500→                if (detected) {
   501→                    window.setInputFormat(detected);
   502→                }
   503→                // Only convert if output format is selected
   504→                if (outputFormat && text.trim()) {
   505→                    window.convert();
   506→                }
   507→            }, 400);
   508→        }
   509→    }
   510→
   511→    editor.on('change', function(cm, change) {
   512→        // Detect immediately on paste, debounce on typing
   513→        const isPaste = change.origin === 'paste';
   514→        debouncedDetectAndConvert(isPaste);
   515→    });
   516→
   517→    function showMessage(text, type) {
   518→        messageEl.textContent = text;
   519→        messageEl.className = 'message ' + type;
   520→        setTimeout(() => {
   521→            messageEl.className = 'message';
   522→        }, 3000);
   523→    }
   524→
   525→    window.setInputFormat = function(format) {
   526→        inputFormat = format;
   527→        editor.setOption('mode', modeMap[format]);
   528→        formatBadge.textContent = format.toUpperCase();
   529→    }
   530→
   531→    window.setOutputFormat = function(format) {
   532→        outputFormat = format;
   533→        editorOutput.setOption('mode', modeMap[format]);
   534→        updateFormatButtons();
   535→
   536→        if (editor.getValue().trim()) {
   537→            window.convert();
   538→        } else {
   539→            editorOutput.setValue('');
   540→        }
   541→    }
   542→
   543→    function updateFormatButtons() {
   544→        document.querySelectorAll('.format-buttons .format-btn').forEach(btn => {
   545→            btn.classList.toggle('active', btn.dataset.format === outputFormat);
   546→        });
   547→    }
   548→
   549→    function parseInput(text, format) {
   550→        switch (format) {
   551→            case 'json':
   552→                return JSON.parse(text);
   553→            case 'yaml':
   554→                return jsyaml.load(text);
   555→            case 'toml':
   556→                if (!TOML) throw new Error('TOML library is still loading, please try again');
   557→                return TOML.parse(text);
   558→            default:
   559→                throw new Error('Unknown input format');
   560→        }
   561→    }
   562→
   563→    function stringify(data, format) {
   564→        switch (format) {
   565→            case 'json':
   566→                return JSON.stringify(data, null, 2);
   567→            case 'yaml':
   568→                return jsyaml.dump(data, { indent: 2, lineWidth: -1 });
   569→            case 'toml':
   570→                return stringifyToml(data);
   571→            default:
   572→                throw new Error('Unknown output format');
   573→        }
   574→    }
   575→
   576→    function stringifyToml(data) {
   577→        if (!TOML) {
   578→            throw new Error('TOML library is still loading, please try again');
   579→        }
   580→        // TOML requires root to be an object/table
   581→        if (Array.isArray(data)) {
   582→            throw new Error('TOML does not support arrays at root level. Wrap in an object like { "items": [...] }');
   583→        }
   584→        if (data === null || typeof data !== 'object') {
   585→            throw new Error('TOML requires an object/table at root level');
   586→        }
   587→        try {
   588→            return TOML.stringify(data);
   589→        } catch (e) {
   590→            // Provide friendlier error messages for common TOML limitations
   591→            const msg = e.message || '';
   592→            if (msg.includes('mixed') || msg.includes('heterogeneous')) {
   593→                throw new Error('TOML arrays must contain values of the same type');
   594→            }
   595→            if (msg.includes('null') || msg.includes('undefined')) {
   596→                throw new Error('TOML does not support null values');
   597→            }
   598→            throw e;
   599→        }
   600→    }
   601→
   602→    window.convert = function() {
   603→        if (!outputFormat) {
   604→            showMessage('Please select an output format', 'error');
   605→            return;
   606→        }
   607→        const text = editor.getValue().trim();
   608→        if (!text) {
   609→            showMessage('Please enter content to convert', 'error');
   610→            return;
   611→        }
   612→
   613→        let data;
   614→        try {
   615→            data = parseInput(text, inputFormat);
   616→        } catch (e) {
   617→            showMessage(`Invalid ${inputFormat.toUpperCase()}: ${e.message}`, 'error');
   618→            return;
   619→        }
   620→
   621→        try {
   622→            const result = stringify(data, outputFormat);
   623→            editorOutput.setValue(result);
   624→            showMessage(`Converted from ${inputFormat.toUpperCase()} to ${outputFormat.toUpperCase()}`, 'success');
   625→        } catch (e) {
   626→            showMessage(`Cannot convert to ${outputFormat.toUpperCase()}: ${e.message}`, 'error');
   627→        }
   628→    }
   629→
   630→    window.copyOutput = function() {
   631→        const result = editorOutput.getValue();
   632→        if (!result) {
   633→            showMessage('Nothing to copy', 'error');
   634→            return;
   635→        }
   636→        navigator.clipboard.writeText(result).then(() => {
   637→            showMessage('Copied to clipboard', 'success');
   638→        }).catch(() => {
   639→            showMessage('Failed to copy', 'error');
   640→        });
   641→    }
   642→
   643→    window.clearAll = function() {
   644→        clearTimeout(debounceTimeout);
   645→        editor.setValue('');
   646→        editor.clearHistory();
   647→        editorOutput.setValue('');
   648→        editorOutput.clearHistory();
   649→        editorOutput.setOption('mode', null);
   650→        formatBadge.textContent = '';
   651→        inputFormat = 'json';
   652→        outputFormat = null;
   653→        editor.setOption('mode', modeMap['json']);
   654→        // Clear active state from output format buttons
   655→        document.querySelectorAll('.format-buttons .format-btn').forEach(btn => {
   656→            btn.classList.remove('active');
   657→        });
   658→        showMessage('Cleared', 'success');
   659→    }
   660→</script>
