   548→    <script src="https://cdn.jsdelivr.net/npm/flatpickr"></script>
   549→    <script src="https://cdn.jsdelivr.net/npm/flatpickr/dist/plugins/confirmDate/confirmDate.js"></script>
   550→    <script>
   551→        const startEl = document.getElementById('start');
   552→        const endEl = document.getElementById('end');
   553→        const useNowEl = document.getElementById('useNow');
   554→        const nameEl = document.getElementById('name');
   555→        const resultCardEl = document.getElementById('resultCard');
   556→        const resultTitleEl = document.getElementById('resultTitle');
   557→        const resultValueEl = document.getElementById('resultValue');
   558→        const messageEl = document.getElementById('message');
   559→
   560→        let intervalId = null;
   561→        let startPicker, endPicker;
   562→
   563→        // Initialize Flatpickr
   564→        const flatpickrConfig = {
   565→            enableTime: true,
   566→            dateFormat: "Y-m-d H:i",
   567→            time_24hr: true,
   568→            allowInput: true,
   569→            disableMobile: true,
   570→            plugins: [new confirmDatePlugin({})]
   571→        };
   572→
   573→        const twoDaysAgo = new Date();
   574→        twoDaysAgo.setDate(twoDaysAgo.getDate() - 2);
   575→        twoDaysAgo.setSeconds(0, 0);
   576→        startPicker = flatpickr(startEl, {
   577→            ...flatpickrConfig,
   578→            defaultDate: twoDaysAgo,
   579→            onChange: (selectedDates) => {
   580→                if (selectedDates.length > 0) {
   581→                    selectedDates[0].setSeconds(0, 0);
   582→                }
   583→            }
   584→        });
   585→
   586→        endPicker = flatpickr(endEl, {
   587→            ...flatpickrConfig,
   588→            onChange: (selectedDates) => {
   589→                if (!useNowEl.checked && selectedDates.length > 0) {
   590→                    selectedDates[0].setSeconds(0, 0);
   591→                }
   592→            }
   593→        });
   594→
   595→        function showMessage(text, type) {
   596→            messageEl.textContent = text;
   597→            messageEl.className = 'message ' + type;
   598→            setTimeout(() => {
   599→                messageEl.className = 'message';
