   601→        }
   602→
   603→        function formatDateTime(date) {
   604→            const year = date.getFullYear();
   605→            const month = String(date.getMonth() + 1).padStart(2, '0');
   606→            const day = String(date.getDate()).padStart(2, '0');
   607→            const hours = String(date.getHours()).padStart(2, '0');
   608→            const minutes = String(date.getMinutes()).padStart(2, '0');
   609→            const seconds = String(date.getSeconds()).padStart(2, '0');
   610→            return `${year}-${month}-${day} ${hours}:${minutes}:${seconds}`;
   611→        }
   612→
   613→        function updateNowDisplay() {
   614→            if (useNowEl.checked) {
   615→                endEl.value = formatDateTime(new Date());
   616→            }
   617→        }
   618→
   619→        // Clear hash when user modifies time
   620→        function clearHash() {
   621→            if (window.location.hash) {
   622→                history.replaceState(null, null, window.location.pathname);
   623→            }
   624→        }
   625→
   626→        useNowEl.addEventListener('change', function () {
   627→            clearHash();
   628→            if (this.checked) {
   629→                endPicker.clear();
   630→                updateNowDisplay();
   631→                if (intervalId) clearInterval(intervalId);
   632→                intervalId = setInterval(() => {
   633→                    updateNowDisplay();
   634→                    if (resultCardEl.style.display !== 'none') {
   635→                        calculate();
   636→                    }
   637→                }, 1000);
   638→            } else {
   639→                // Set end time to current time (without seconds)
   640→                const now = new Date();
   641→                now.setSeconds(0, 0);
   642→                endPicker.setDate(now);
   643→                if (intervalId) {
   644→                    clearInterval(intervalId);
   645→                    intervalId = null;
   646→                }
   647→            }
   648→            updateShareButton();
   649→        });
   650→
   651→        // Listen for Flatpickr changes to update share button and clear hash
   652→        startEl.addEventListener('change', () => {
   653→            updateShareButton();
   654→            clearHash();
   655→        });
   656→        endEl.addEventListener('change', () => {
   657→            updateShareButton();
   658→            clearHash();
   659→        });
