   661→        function calculate() {
   662→            const startDate = startPicker.selectedDates[0];
   663→            if (!startDate) {
   664→                showMessage('Please enter a start time', 'error');
   665→                return;
   666→            }
   667→
   668→            let end;
   669→            if (useNowEl.checked) {
   670→                end = new Date();
   671→            } else {
   672→                const endDate = endPicker.selectedDates[0];
   673→                if (!endDate) {
   674→                    showMessage('Please enter an end time or use NOW', 'error');
   675→                    return;
   676→                }
   677→                end = endDate;
   678→            }
   679→
   680→            let diff = end - startDate;
   681→            const isNegative = diff < 0;
   682→            diff = Math.abs(diff);
   683→
   684→            const days = Math.floor(diff / (1000 * 60 * 60 * 24));
   685→            const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
   686→            const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
   687→            const seconds = Math.floor((diff % (1000 * 60)) / 1000);
   688→
   689→            // Format main display
   690→            let parts = [];
   691→            if (days > 0) parts.push(days + 'd');
   692→            if (hours > 0 || days > 0) parts.push(hours + 'h');
   693→            if (minutes > 0 || hours > 0 || days > 0) parts.push(minutes + 'm');
   694→            parts.push(seconds + 's');
   695→
   696→            const displayValue = (isNegative ? '-' : '') + parts.join(' ');
   697→
   698→            // Update UI
   699→            resultCardEl.style.display = 'block';
   700→            resultValueEl.textContent = displayValue;
   701→            resultValueEl.className = 'result-value' + (isNegative ? ' negative' : '');
   702→
   703→            document.getElementById('days').textContent = days;
   704→            document.getElementById('hours').textContent = hours;
   705→            document.getElementById('minutes').textContent = minutes;
   706→            document.getElementById('seconds').textContent = seconds;
   707→
   708→            const totalSeconds = Math.floor(diff / 1000);
   709→            document.getElementById('totalSeconds').textContent =
   710→                `Total: ${totalSeconds.toLocaleString()} seconds`;
   711→
   712→            // Update title (use name if provided, otherwise "Duration")
   713→            const name = nameEl.value.trim();
   714→            let titleText = name || 'Duration';
   715→            if (isNegative && !name) {
   716→                titleText = 'Duration (negative)';
   717→            }
   718→
   719→            if (useNowEl.checked) {
   720→                // Set title text safely
   721→                resultTitleEl.textContent = titleText;
   722→
   723→                // Create and append badge element
   724→                const badge = document.createElement('span');
   725→                badge.className = 'live-badge';
   726→                badge.textContent = 'LIVE';
   727→                resultTitleEl.appendChild(badge);
   728→            } else {
   729→                resultTitleEl.textContent = titleText;
   730→            }
   731→        }
