   733→        function clearAll() {
   734→            startPicker.clear();
   735→            endPicker.clear();
   736→            endEl.value = '';
   737→            nameEl.value = '';
   738→            useNowEl.checked = false;
   739→            resultCardEl.style.display = 'none';
