   751→        // Base62 charset
   752→        const BASE62 = 'REDACTED';
   753→
   754→        // Encode number to Base62
   755→        function encodeBase62(num) {
   756→            if (num === 0n) return '0';
   757→            let arr = [];
   758→            while (num > 0n) {
   759→                arr.push(BASE62[Number(num % 62n)]);
   760→                num = num / 62n;
   761→            }
   762→            return arr.reverse().join('');
   763→        }
   764→
   765→        // Decode Base62 to number
   766→        function decodeBase62(str) {
   767→            let num = 0n;
   768→            for (let i = 0; i < str.length; i++) {
   769→                const idx = BASE62.indexOf(str[i]);
   770→                if (idx === -1) throw new Error('Invalid character');
   771→                num = num * 62n + BigInt(idx);
   772→            }
   773→            return num;
   774→        }
   775→
   776→        // NOW marker (max 32-bit value: 4294967295)
   777→        const NOW_MARKER = 0xFFFFFFFF;
   778→
   779→        // Base64URL encode (URL-safe, no padding)
   780→        function encodeBase64URL(str) {
   781→            const bytes = new TextEncoder().encode(str);
   782→            let binary = '';
   783→            bytes.forEach(b => binary += String.fromCharCode(b));
   784→            return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
   785→        }
   786→
   787→        // Base64URL decode
   788→        function decodeBase64URL(str) {
   789→            str = str.replace(/-/g, '+').replace(/_/g, '/');
   790→            while (str.length % 4) str += '=';
   791→            const binary = atob(str);
   792→            const bytes = new Uint8Array(binary.length);
   793→            for (let i = 0; i < binary.length; i++) {
   794→                bytes[i] = binary.charCodeAt(i);
   795→            }
   796→            return new TextDecoder().decode(bytes);
   797→        }
   798→
   799→        // Encode share data to Base62
   800→        function encodeShareData(startTs, endTs, isNow) {
   801→            // If NOW mode, use marker for endTs
   802→            const endValue = isNow ? NOW_MARKER : endTs;
   803→            // Pack two 32-bit timestamps into a single number
   804→            // startTs in high 32 bits, endTs in low 32 bits
   805→            const packed = (BigInt(startTs) << 32n) | BigInt(endValue);
   806→            return encodeBase62(packed);
   807→        }
   808→
   809→        // Decode share data from Base62
   810→        function decodeShareData(base62) {
   811→            try {
   812→                const packed = decodeBase62(base62);
   813→                const startTs = Number(packed >> 32n);
   814→                const endTs = Number(packed & 0xFFFFFFFFn);
   815→                const isNow = endTs === NOW_MARKER;
   816→                return { s: startTs, e: endTs, isNow };
   817→            } catch (e) {
   818→                // Invalid hash, ignore
   819→            }
   820→            return null;
   821→        }
   822→
   823→        // Share URL function
   824→        function shareUrl() {
   825→            const startDate = startPicker.selectedDates[0];
   826→
   827→            if (!startDate) {
   828→                showMessage('Please set start time', 'error');
   829→                return;
   830→            }
   831→
   832→            const startTs = Math.floor(startDate.getTime() / 1000);
   833→            const isNow = useNowEl.checked;
   834→            let endTs = 0;
   835→
   836→            if (!isNow) {
   837→                const endDate = endPicker.selectedDates[0];
   838→                if (!endDate) {
   839→                    showMessage('Please set end time or use NOW', 'error');
   840→                    return;
   841→                }
   842→                endTs = Math.floor(endDate.getTime() / 1000);
   843→            }
   844→
   845→            const timeHash = encodeShareData(startTs, endTs, isNow);
   846→            const name = nameEl.value.trim();
   847→
   848→            // Format: #s={base62} or #s={base62}.{base64url_name}
   849→            let hash = timeHash;
   850→            if (name) {
   851→                hash += '.' + encodeBase64URL(name);
   852→            }
   853→
   854→            const url = window.location.origin + window.location.pathname + '#s=' + hash;
   855→
   856→            // Update current URL
   857→            history.pushState(null, null, '#s=' + hash);
   858→
   859→            navigator.clipboard.writeText(url).then(() => {
   860→                showMessage('Share link copied to clipboard!', 'success');
   861→            }).catch(() => {
   862→                showMessage('Failed to copy link', 'error');
   863→            });
   864→        }
   865→
   866→        // Update share button state
   867→        function updateShareButton() {
   868→            const shareBtn = document.getElementById('shareBtn');
   869→            const hasStart = startPicker.selectedDates.length > 0;
   870→            const hasEnd = endPicker.selectedDates.length > 0;
   871→            const isNowMode = useNowEl.checked;
   872→
   873→            // Enable if start time is set, and either end time is set or NOW is checked
   874→            shareBtn.disabled = !hasStart || (!hasEnd && !isNowMode);
   875→        }
   876→
   877→        // Parse hash on page load
   878→        function parseHash() {
   879→            const hash = window.location.hash;
   880→            if (hash && hash.startsWith('#s=')) {
   881→                const hashContent = hash.substring(3);
   882→
   883→                // Check if there's a name: format is {base62}.{base64url_name}
   884→                const dotIndex = hashContent.indexOf('.');
   885→                let timeHash, name = '';
   886→
   887→                if (dotIndex !== -1) {
   888→                    timeHash = hashContent.substring(0, dotIndex);
   889→                    try {
   890→                        name = decodeBase64URL(hashContent.substring(dotIndex + 1));
   891→                    } catch (e) {
   892→                        // Invalid name encoding, ignore
   893→                    }
   894→                } else {
   895→                    timeHash = hashContent;
   896→                }
   897→
   898→                const data = decodeShareData(timeHash);
   899→
   900→                if (data) {
   901→                    const startDate = new Date(data.s * 1000);
   902→                    startDate.setSeconds(0, 0);
   903→                    startPicker.setDate(startDate);
   904→
   905→                    if (data.isNow) {
   906→                        // NOW mode
   907→                        useNowEl.checked = true;
   908→                        updateNowDisplay();
   909→                        // Start live update timer
   910→                        if (intervalId) clearInterval(intervalId);
   911→                        intervalId = setInterval(() => {
   912→                            updateNowDisplay();
   913→                            if (resultCardEl.style.display !== 'none') {
   914→                                calculate();
   915→                            }
   916→                        }, 1000);
   917→                    } else {
   918→                        // Fixed end time
   919→                        const endDate = new Date(data.e * 1000);
   920→                        endDate.setSeconds(0, 0);
   921→                        endPicker.setDate(endDate);
   922→                        useNowEl.checked = false;
   923→                    }
   924→
   925→                    // Set name if present
   926→                    if (name) {
   927→                        nameEl.value = name;
   928→                    }
   929→
   930→                    calculate();
   931→                }
   932→            }
   933→        }
   934→
   935→        // Parse hash on load
   936→        parseHash();
   937→
   938→        // Update share button state on init
   939→        updateShareButton();
   940→    </script>
