   308→<div class="container">
   309→    <a class="back-link" href="index.html">← Back to Tools</a>
   310→    <h1>Password Generator</h1>
   311→    <p class="subtitle">Generate secure random passwords</p>
   312→
   313→    <div class="card">
   314→        <div class="label">Generated Password</div>
   315→        <div class="password-display" id="password" onclick="copyPassword()" title="Click to copy"></div>
   316→        <div class="strength-bar">
   317→            <div class="strength-fill" id="strengthFill"></div>
   318→        </div>
   319→        <div class="strength-text" id="strengthText">Password strength</div>
   320→    </div>
   321→
   322→    <div class="card">
   323→        <div class="label">Password Length: <span style="color: #00d9ff;">8-128</span></div>
   324→        <div class="length-control">
   325→            <input class="length-slider" id="lengthSlider" max="128" min="8" type="range" value="16">
   326→            <span class="length-value" id="lengthValue">16</span>
   327→        </div>
   328→    </div>
   329→
   330→    <div class="card">
   331→        <div class="label">Character Types</div>
   332→        <div class="options">
   333→            <label class="checkbox-label">
   334→                <input checked id="uppercase" type="checkbox">
   335→                <span>Uppercase (A-Z)</span>
   336→            </label>
   337→            <label class="checkbox-label">
   338→                <input checked id="lowercase" type="checkbox">
   339→                <span>Lowercase (a-z)</span>
   340→            </label>
   341→            <label class="checkbox-label">
   342→                <input checked id="numbers" type="checkbox">
   343→                <span>Numbers (0-9)</span>
   344→            </label>
   345→            <label class="checkbox-label">
   346→                <input checked id="symbols" type="checkbox">
   347→                <span>Symbols (!@#$%)</span>
   348→            </label>
   349→        </div>
   350→    </div>
   351→
   352→    <div class="button-group">
   353→        <button class="btn-generate" onclick="generate()">Generate Password</button>
   354→        <button class="btn-copy" onclick="copyPassword()">Copy</button>
   355→    </div>
   356→</div>
   357→
   358→<div class="message" id="message"></div>
   359→
   360→<script>
   361→    const CHAR_SETS = {
   362→        uppercase: 'REDACTED',
   363→        lowercase: 'REDACTED',
   364→        numbers: '0123456789',
   365→        symbols: '!@#$%^&*()_+-=[]{}|;:,.<>?'
   366→    };
   367→
   368→    const passwordEl = document.getElementById('password');
   369→    const strengthFillEl = document.getElementById('strengthFill');
   370→    const strengthTextEl = document.getElementById('strengthText');
   371→    const lengthSliderEl = document.getElementById('lengthSlider');
   372→    const lengthValueEl = document.getElementById('lengthValue');
   373→    const messageEl = document.getElementById('message');
   374→
   375→    // Update length display
   376→    lengthSliderEl.addEventListener('input', () => {
   377→        lengthValueEl.textContent = lengthSliderEl.value;
   378→        generate();
   379→    });
   380→
   381→    // Auto-generate on option change
   382→    ['uppercase', 'lowercase', 'numbers', 'symbols'].forEach(id => {
   383→        document.getElementById(id).addEventListener('change', () => {
   384→            // Ensure at least one option is selected
   385→            const anyChecked = ['uppercase', 'lowercase', 'numbers', 'symbols']
   386→                .some(id => document.getElementById(id).checked);
   387→            if (!anyChecked) {
   388→                document.getElementById(id).checked = true;
   389→                showMessage('Please select at least one character type', 'error');
   390→                return;
   391→            }
   392→            generate();
   393→        });
   394→    });
   395→
   396→    function showMessage(text, type) {
   397→        messageEl.textContent = text;
   398→        messageEl.className = 'message ' + type;
   399→        setTimeout(() => {
   400→            messageEl.className = 'message';
   401→        }, 3000);
   402→    }
   403→
   404→    function generate() {
   405→        const length = parseInt(lengthSliderEl.value);
   406→        let chars = '';
   407→        let passwordChars = [];
   408→
   409→        // Collect selected character sets
   410→        const selectedSets = [];
   411→        if (document.getElementById('uppercase').checked) {
   412→            chars += CHAR_SETS.uppercase;
   413→            selectedSets.push(CHAR_SETS.uppercase);
   414→        }
   415→        if (document.getElementById('lowercase').checked) {
   416→            chars += CHAR_SETS.lowercase;
   417→            selectedSets.push(CHAR_SETS.lowercase);
   418→        }
   419→        if (document.getElementById('numbers').checked) {
   420→            chars += CHAR_SETS.numbers;
   421→            selectedSets.push(CHAR_SETS.numbers);
   422→        }
   423→        if (document.getElementById('symbols').checked) {
   424→            chars += CHAR_SETS.symbols;
   425→            selectedSets.push(CHAR_SETS.symbols);
   426→        }
   427→
   428→        // Ensure at least one character from each selected set
   429→        const guaranteedCount = Math.min(selectedSets.length, length);
   430→        const guaranteedRandom = new Uint32Array(guaranteedCount);
   431→        crypto.getRandomValues(guaranteedRandom);
   432→        for (let i = 0; i < guaranteedCount; i++) {
   433→            const set = selectedSets[i];
   434→            passwordChars.push(set.charAt(guaranteedRandom[i] % set.length));
   435→        }
   436→
   437→        // Fill remaining with random characters from combined set
   438→        const remainingCount = length - guaranteedCount;
   439→        if (remainingCount > 0) {
   440→            const remainingRandom = new Uint32Array(remainingCount);
   441→            crypto.getRandomValues(remainingRandom);
   442→            for (let i = 0; i < remainingCount; i++) {
   443→                passwordChars.push(chars.charAt(remainingRandom[i] % chars.length));
   444→            }
   445→        }
   446→
   447→        // Fisher-Yates shuffle
   448→        const shuffleRandom = new Uint32Array(passwordChars.length);
   449→        crypto.getRandomValues(shuffleRandom);
   450→        for (let i = passwordChars.length - 1; i > 0; i--) {
   451→            const j = shuffleRandom[i] % (i + 1);
   452→            [passwordChars[i], passwordChars[j]] = [passwordChars[j], passwordChars[i]];
   453→        }
   454→
   455→        passwordEl.textContent = passwordChars.join('');
   456→        updateStrength(passwordChars.join(''));
   457→    }
   458→
   459→    function updateStrength(password) {
   460→        let score = 0;
   461→
   462→        // Length score
   463→        if (password.length >= 12) score += 1;
   464→        if (password.length >= 16) score += 1;
   465→
   466→        // Character variety
   467→        if (/[a-z]/.test(password)) score += 1;
   468→        if (/[A-Z]/.test(password)) score += 1;
   469→        if (/[0-9]/.test(password)) score += 1;
   470→        if (/[^a-zA-Z0-9]/.test(password)) score += 1;
   471→
   472→        strengthFillEl.className = 'strength-fill';
   473→
   474→        if (score <= 2) {
   475→            strengthFillEl.classList.add('weak');
   476→            strengthTextEl.textContent = 'Weak';
   477→            strengthTextEl.style.color = '#ef4444';
   478→        } else if (score <= 4) {
   479→            strengthFillEl.classList.add('medium');
   480→            strengthTextEl.textContent = 'Medium';
   481→            strengthTextEl.style.color = '#f59e0b';
   482→        } else {
   483→            strengthFillEl.classList.add('strong');
   484→            strengthTextEl.textContent = 'Strong';
   485→            strengthTextEl.style.color = '#10b981';
   486→        }
   487→    }
   488→
   489→    function copyPassword() {
   490→        const password = passwordEl.textContent;
   491→        if (!password) {
   492→            showMessage('No password to copy', 'error');
   493→            return;
   494→        }
   495→
   496→        navigator.clipboard.writeText(password).then(() => {
   497→            showMessage('Password copied to clipboard', 'success');
   498→        }).catch(() => {
   499→            showMessage('Failed to copy', 'error');
   500→        });
   501→    }
   502→
   503→    // Generate on load
   504→    generate();
   505→</script>
   506→</body>
