   354→                <div class="info-item">
   355→                    <div class="info-label">Key Type</div>
   356→                    <div class="info-value" id="keyType">-</div>
   357→                </div>
   358→                <div class="info-item">
   359→                    <div class="info-label">Key Size</div>
   360→                    <div class="info-value" id="keySize">-</div>
   361→                </div>
   362→                <div class="info-item">
   363→                    <div class="info-label">Format</div>
   364→                    <div class="info-value" id="keyFormat">-</div>
   365→                </div>
   366→                <div class="info-item">
   367→                    <div class="info-label">Version</div>
   368→                    <div class="info-value" id="keyVersion">-</div>
   369→                </div>
   370→            </div>
