   380→<script>
   381→    const inputEl = document.getElementById('input');
   382→    const messageEl = document.getElementById('message');
   383→    const resultEl = document.getElementById('result');
   384→
   385→    // Auto-resize textarea
   386→    function autoResize() {
   387→        inputEl.style.height = 'auto';
   388→        inputEl.style.height = inputEl.scrollHeight + 'px';
   389→    }
   390→
   391→    inputEl.addEventListener('input', autoResize);
   392→
   393→    // Initial resize
   394→    autoResize();
   395→
   396→    function showMessage(text, type) {
   397→        messageEl.textContent = text;
   398→        messageEl.className = 'message ' + type;
   399→        setTimeout(() => {
   400→            messageEl.className = 'message';
   401→        }, 5000);
   402→    }
   403→
   404→    // Base64 decode
   405→    function base64Decode(str) {
   406→        const binary = atob(str);
   407→        const bytes = new Uint8Array(binary.length);
   408→        for (let i = 0; i < binary.length; i++) {
   409→            bytes[i] = binary.charCodeAt(i);
   410→        }
   411→        return bytes;
   412→    }
   413→
   414→    // ASN.1 DER Parser
   415→    class ASN1Parser {
   416→        constructor(data) {
   417→            this.data = data;
   418→            this.pos = 0;
   419→        }
   420→
   421→        readByte() {
   422→            return this.data[this.pos++];
   423→        }
   424→
   425→        readLength() {
   426→            let length = this.readByte();
   427→            if (length & 0x80) {
   428→                const numBytes = length & 0x7f;
   429→                length = 0;
   430→                for (let i = 0; i < numBytes; i++) {
   431→                    length = (length << 8) | this.readByte();
   432→                }
   433→            }
   434→            return length;
   435→        }
   436→
   437→        readTag() {
   438→            return this.readByte();
   439→        }
   440→
   441→        readInteger() {
   442→            const tag = this.readTag();
   443→            if (tag !== 0x02) {
   444→                throw new Error('Expected INTEGER tag');
   445→            }
   446→            const length = this.readLength();
   447→            const value = this.data.slice(this.pos, this.pos + length);
   448→            this.pos += length;
   449→            return value;
   450→        }
   451→
   452→        readSequence() {
   453→            const tag = this.readTag();
   454→            if (tag !== 0x30) {
   455→                throw new Error('Expected SEQUENCE tag');
   456→            }
   457→            const length = this.readLength();
   458→            return length;
   459→        }
   460→
   461→        readOID() {
   462→            const tag = this.readTag();
   463→            if (tag !== 0x06) {
   464→                throw new Error('Expected OID tag');
   465→            }
   466→            const length = this.readLength();
   467→            const value = this.data.slice(this.pos, this.pos + length);
   468→            this.pos += length;
   469→            return value;
   470→        }
   471→
   472→        readOctetString() {
   473→            const tag = this.readTag();
   474→            if (tag !== 0x04) {
   475→                throw new Error('Expected OCTET STRING tag');
   476→            }
   477→            const length = this.readLength();
   478→            const value = this.data.slice(this.pos, this.pos + length);
   479→            this.pos += length;
   480→            return value;
   481→        }
   482→
   483→        skip(length) {
   484→            this.pos += length;
   485→        }
   486→    }
   487→
   488→    // Convert bytes to hex string
   489→    function bytesToHex(bytes) {
   490→        return Array.from(bytes).map(b => b.toString(16).padStart(2, '0')).join('');
   491→    }
   492→
   493→    // Calculate bit length of a big integer
   494→    function getBitLength(bytes) {
   495→        let i = 0;
   496→        // Skip leading zero bytes
   497→        while (i < bytes.length && bytes[i] === 0) i++;
   498→        if (i >= bytes.length) return 0;
   499→
   500→        const firstByte = bytes[i];
   501→        // Safety check for zero byte (should not happen after while loop, but defensive)
   502→        if (firstByte === 0) return 0;
   503→
   504→        const remainingBytes = bytes.length - i - 1;
   505→        // Calculate bits in the first non-zero byte
   506→        const firstByteBits = 32 - Math.clz32(firstByte);
   507→        return remainingBytes * 8 + firstByteBits;
   508→    }
   509→
   510→    // Parse RSA private key
   511→    function parseRSAKey(pemData) {
   512→        let format = 'PKCS#1';
   513→        let base64Data = '';
   514→
   515→        // Check format
   516→        if (pemData.includes('REDACTED', '')
   520→                .replace('-----END RSA PRIVATE KEY-----', '')
   521→                .replace(/\s/g, '');
   522→        } else if (pemData.includes('REDACTED', '')
   526→                .replace('-----END PRIVATE KEY-----', '')
   527→                .replace(/\s/g, '');
   528→        } else {
   529→            throw new Error('Unsupported key format. Please use PEM format RSA private key');
   530→        }
   531→
   532→        const derData = base64Decode(base64Data);
   533→        const parser = new ASN1Parser(derData);
   534→
   535→        let components = {};
   536→
   537→        if (format === 'PKCS#8') {
   538→            // PKCS#8 format
   539→            parser.readSequence(); // outer sequence
   540→            parser.readInteger(); // version
   541→            parser.readSequence(); // algorithm identifier sequence
   542→            parser.readOID(); // algorithm OID
   543→
   544→            // Skip NULL if present
   545→            if (parser.data[parser.pos] === 0x05) {
   546→                parser.pos += 2;
   547→            }
   548→
   549→            const privateKeyData = parser.readOctetString();
   550→            const innerParser = new ASN1Parser(privateKeyData);
   551→            innerParser.readSequence();
   552→
   553→            components.version = innerParser.readInteger();
   554→            components.modulus = innerParser.readInteger();
   555→            components.publicExponent = innerParser.readInteger();
   556→            components.privateExponent = innerParser.readInteger();
   557→            components.prime1 = innerParser.readInteger();
   558→            components.prime2 = innerParser.readInteger();
   559→            components.exponent1 = innerParser.readInteger();
   560→            components.exponent2 = innerParser.readInteger();
   561→            components.coefficient = innerParser.readInteger();
   562→        } else {
   563→            // PKCS#1 format
   564→            parser.readSequence();
   565→            components.version = parser.readInteger();
   566→            components.modulus = parser.readInteger();
   567→            components.publicExponent = parser.readInteger();
   568→            components.privateExponent = parser.readInteger();
   569→            components.prime1 = parser.readInteger();
   570→            components.prime2 = parser.readInteger();
   571→            components.exponent1 = parser.readInteger();
   572→            components.exponent2 = parser.readInteger();
   573→            components.coefficient = parser.readInteger();
   574→        }
   575→
   576→        return {
   577→            format,
   578→            components,
   579→            keySize: getBitLength(components.modulus)
   580→        };
   581→    }
   582→
   583→    function parseKey() {
   584→        const pemData = inputEl.value.trim();
   585→        if (!pemData) {
   586→            showMessage('Please enter RSA private key', 'error');
   587→            return;
   588→        }
   589→
   590→        try {
   591→            const result = parseRSAKey(pemData);
   592→            displayResult(result);
   593→            showMessage('Parsed successfully', 'success');
   594→        } catch (e) {
   595→            showMessage('Parse failed: ' + e.message, 'error');
   596→            resultEl.classList.remove('show');
   597→        }
   598→    }
   599→
   600→    function displayResult(result) {
   601→        resultEl.classList.add('show');
   602→
   603→        document.getElementById('keyType').textContent = 'RSA';
   604→        document.getElementById('keySize').textContent = result.keySize + ' bits';
   605→        document.getElementById('keyFormat').textContent = result.format;
   606→        document.getElementById('keyVersion').textContent = 'v' + (parseInt(bytesToHex(result.components.version), 16) + 1);
   607→
   608→        const componentNames = {
   609→            modulus: {name: 'Modulus (n)', desc: 'n = p × q'},
   610→            publicExponent: {name: 'Public Exponent (e)', desc: 'public exponent'},
   611→            privateExponent: {name: 'Private Exponent (d)', desc: 'private exponent'},
   612→            prime1: {name: 'Prime 1 (p)', desc: 'first prime'},
   613→            prime2: {name: 'Prime 2 (q)', desc: 'second prime'},
   614→            exponent1: {name: 'Exponent 1 (dp)', desc: 'd mod (p-1)'},
   615→            exponent2: {name: 'Exponent 2 (dq)', desc: 'd mod (q-1)'},
   616→            coefficient: {name: 'Coefficient (qInv)', desc: 'q⁻¹ mod p'}
   617→        };
   618→
   619→        const componentsEl = document.getElementById('components');
   620→        componentsEl.innerHTML = '';
   621→
   622→        for (const [key, value] of Object.entries(result.components)) {
   623→            if (key === 'version') continue;
   624→
   625→            const info = componentNames[key];
   626→            const hex = bytesToHex(value);
   627→            const bitLen = getBitLength(value);
   628→
   629→            const div = document.createElement('div');
   630→            div.className = 'component';
   631→            div.innerHTML = `
   632→                    <div class="component-header" onclick="this.parentElement.classList.toggle('open')">
   633→                        <div>
   634→                            <span class="component-name">${info.name}</span>
   635→                            <span class="component-meta"> - ${info.desc}</span>
   636→                        </div>
   637→                        <div>
   638→                            <span class="component-meta">${bitLen} bits</span>
   639→                            <span class="toggle-icon">▼</span>
   640→                        </div>
   641→                    </div>
   642→                    <div class="component-body">
   643→                        <div class="component-value" id="value-${key}">${hex}</div>
   644→                        <button class="copy-btn" onclick="copyValue('${key}')">Copy</button>
   645→                    </div>
   646→                `;
   647→            componentsEl.appendChild(div);
   648→        }
   649→    }
   650→
   651→    function copyValue(key) {
   652→        const el = document.getElementById('value-' + key);
   653→        navigator.clipboard.writeText(el.textContent).then(() => {
   654→            showMessage('Copied to clipboard', 'success');
   655→        });
   656→    }
   657→
   658→    function loadSample() {
   659→        // This is a sample 512-bit RSA key for demonstration only
   660→        inputEl.value = `REDACTED`;
   669→        autoResize();
   670→    }
   671→
   672→    function clearAll() {
   673→        inputEl.value = '';
   674→        resultEl.classList.remove('show');
   675→        autoResize();
   676→        showMessage('Cleared', 'success');
   677→    }
   678→</script>
