   587→        return div.innerHTML;
   588→    }
   589→
   590→    // Base64 decode
   591→    function base64Decode(str) {
   592→        const binary = atob(str);
   593→        const bytes = new Uint8Array(binary.length);
   594→        for (let i = 0; i < binary.length; i++) {
   595→            bytes[i] = binary.charCodeAt(i);
   596→        }
   597→        return bytes;
   598→    }
   599→
   600→    // ASN.1 OID mapping
   601→    const OID_MAP = {
   602→        '2.5.4.3': 'CN',
   603→        '2.5.4.6': 'C',
   604→        '2.5.4.7': 'L',
   605→        '2.5.4.8': 'ST',
   606→        '2.5.4.10': 'O',
   607→        '2.5.4.11': 'OU',
   608→        '1.2.840.113549.1.1.1': 'RSA',
   609→        '1.2.840.113549.1.1.5': 'SHA-1 with RSA',
   610→        '1.2.840.113549.1.1.11': 'SHA-256 with RSA',
   611→        '1.2.840.113549.1.1.12': 'SHA-384 with RSA',
   612→        '1.2.840.113549.1.1.13': 'SHA-512 with RSA',
   613→        '1.2.840.10045.2.1': 'EC',
   614→        '1.2.840.10045.4.3.2': 'ECDSA with SHA-256',
   615→        '1.2.840.10045.4.3.3': 'ECDSA with SHA-384',
   616→        '2.5.29.14': 'Subject Key Identifier',
   617→        '2.5.29.15': 'Key Usage',
   618→        '2.5.29.17': 'Subject Alternative Name',
   619→        '2.5.29.19': 'Basic Constraints',
   620→        '2.5.29.35': 'Authority Key Identifier',
   621→        '2.5.29.37': 'Extended Key Usage',
   622→        '1.3.6.1.5.5.7.1.1': 'Authority Info Access',
   623→        '2.5.29.31': 'CRL Distribution Points',
   624→        '2.5.29.32': 'Certificate Policies'
   625→    };
   626→
   627→    const OID_NAMES = {
   628→        'CN': 'Common Name',
   629→        'C': 'Country',
   630→        'L': 'Locality',
   631→        'ST': 'State/Province',
   632→        'O': 'Organization',
   633→        'OU': 'Organizational Unit'
   634→    };
   635→
   636→    // ASN.1 Parser
   637→    class ASN1 {
   638→        constructor(data, offset = 0) {
   639→            this.data = data;
   640→            this.pos = offset;
   641→        }
   642→
   643→        peek() {
   644→            return this.data[this.pos];
   645→        }
   646→
   647→        readByte() {
   648→            return this.data[this.pos++];
   649→        }
   650→
   651→        readLength() {
   652→            let len = this.readByte();
   653→            if (len & 0x80) {
   654→                const numBytes = len & 0x7f;
   655→                len = 0;
   656→                for (let i = 0; i < numBytes; i++) {
   657→                    len = (len << 8) | this.readByte();
   658→                }
   659→            }
   660→            return len;
   661→        }
   662→
   663→        readTag() {
   664→            return this.readByte();
   665→        }
   666→
   667→        readTLV() {
   668→            const tag = this.readTag();
   669→            const length = this.readLength();
   670→            const value = this.data.slice(this.pos, this.pos + length);
   671→            this.pos += length;
   672→            return {tag, length, value};
   673→        }
   674→
   675→        readSequence() {
   676→            const tag = this.readTag();
   677→            if (tag !== 0x30) throw new Error('Expected SEQUENCE');
   678→            return this.readLength();
   679→        }
   680→
   681→        readOID() {
   682→            const {tag, value} = this.readTLV();
   683→            if (tag !== 0x06) throw new Error('Expected OID');
   684→
   685→            let oid = Math.floor(value[0] / 40) + '.' + (value[0] % 40);
   686→            let val = 0;
   687→            for (let i = 1; i < value.length; i++) {
   688→                val = (val << 7) | (value[i] & 0x7f);
   689→                if (!(value[i] & 0x80)) {
   690→                    oid += '.' + val;
   691→                    val = 0;
   692→                }
   693→            }
   694→            return oid;
   695→        }
   696→
   697→        readInteger() {
   698→            const {tag, value} = this.readTLV();
   699→            if (tag !== 0x02) throw new Error('Expected INTEGER');
   700→            return value;
   701→        }
   702→
   703→        readBitString() {
   704→            const {tag, value} = this.readTLV();
   705→            if (tag !== 0x03) throw new Error('Expected BIT STRING');
   706→            return value.slice(1); // Skip unused bits byte
   707→        }
   708→
   709→        readUTCTime() {
   710→            const {tag, value} = this.readTLV();
   711→            const str = String.fromCharCode(...value);
   712→            let year = parseInt(str.substr(0, 2));
   713→            year += year < 50 ? 2000 : 1900;
   714→            const month = parseInt(str.substr(2, 2)) - 1;
   715→            const day = parseInt(str.substr(4, 2));
   716→            const hour = parseInt(str.substr(6, 2));
   717→            const min = parseInt(str.substr(8, 2));
   718→            const sec = parseInt(str.substr(10, 2));
   719→            return new Date(Date.UTC(year, month, day, hour, min, sec));
   720→        }
   721→
   722→        readGeneralizedTime() {
   723→            const {tag, value} = this.readTLV();
   724→            const str = String.fromCharCode(...value);
   725→            const year = parseInt(str.substr(0, 4));
   726→            const month = parseInt(str.substr(4, 2)) - 1;
   727→            const day = parseInt(str.substr(6, 2));
   728→            const hour = parseInt(str.substr(8, 2));
   729→            const min = parseInt(str.substr(10, 2));
   730→            const sec = parseInt(str.substr(12, 2));
   731→            return new Date(Date.UTC(year, month, day, hour, min, sec));
   732→        }
   733→
   734→        readTime() {
   735→            const tag = this.peek();
   736→            if (tag === 0x17) return this.readUTCTime();
   737→            if (tag === 0x18) return this.readGeneralizedTime();
   738→            throw new Error('Expected Time');
   739→        }
   740→
   741→        readString() {
   742→            const {tag, value} = this.readTLV();
   743→            return new TextDecoder().decode(value);
   744→        }
   745→
   746→        skip(length) {
   747→            this.pos += length;
   748→        }
   749→    }
   750→
   751→    // Parse X.509 certificate
   752→    function parseCertificate(pem) {
   753→        const base64 = pem
   754→            .replace(/-----BEGIN CERTIFICATE-----/, '')
   755→            .replace(/-----END CERTIFICATE-----/, '')
   756→            .replace(/\s/g, '');
   757→
   758→        const der = base64Decode(base64);
   759→        const cert = {};
   760→
   761→        const asn = new ASN1(der);
   762→
   763→        // Certificate SEQUENCE
   764→        asn.readSequence();
   765→
   766→        // TBSCertificate SEQUENCE
   767→        const tbsStart = asn.pos;
   768→        const tbsLen = asn.readSequence();
   769→        const tbsEnd = asn.pos + tbsLen;
   770→
   771→        // Version (optional, context tag [0])
   772→        if (asn.peek() === 0xa0) {
   773→            asn.readByte(); // tag
   774→            asn.readLength();
   775→            const versionBytes = asn.readInteger();
   776→            cert.version = versionBytes[0] + 1;
   777→        } else {
   778→            cert.version = 1;
   779→        }
   780→
   781→        // Serial Number
   782→        const serialBytes = asn.readInteger();
   783→        cert.serialNumber = Array.from(serialBytes).map(b => b.toString(16).padStart(2, '0')).join(':');
   784→
   785→        // Signature Algorithm
   786→        asn.readSequence();
   787→        cert.signatureAlgorithm = OID_MAP[asn.readOID()] || 'Unknown';
   788→        // Skip to end of algorithm sequence
   789→        while (asn.peek() === 0x05 || asn.peek() === 0x06) {
   790→            asn.readTLV();
   791→        }
   792→
   793→        // Issuer
   794→        cert.issuer = parseDistinguishedName(asn);
   795→
   796→        // Validity
   797→        asn.readSequence();
   798→        cert.notBefore = asn.readTime();
   799→        cert.notAfter = asn.readTime();
   800→
   801→        // Subject
   802→        cert.subject = parseDistinguishedName(asn);
   803→
   804→        // Subject Public Key Info
   805→        const spkiStart = asn.pos;
   806→        asn.readSequence();
   807→        asn.readSequence();
   808→        cert.publicKeyAlgorithm = OID_MAP[asn.readOID()] || 'Unknown';
   809→
   810→        // Skip remaining algorithm params
   811→        while (asn.peek() !== 0x03) {
   812→            asn.readTLV();
   813→        }
   814→
   815→        const pubKeyBits = asn.readBitString();
   816→
   817→        // Estimate key size
   818→        if (cert.publicKeyAlgorithm === 'RSA') {
   819→            const keyAsn = new ASN1(pubKeyBits);
   820→            keyAsn.readSequence();
   821→            const modulus = keyAsn.readInteger();
   822→            let bitLen = 0;
   823→            for (let i = 0; i < modulus.length; i++) {
   824→                if (modulus[i] !== 0) {
   825→                    const firstByte = modulus[i];
   826→                    const firstByteBits = 32 - Math.clz32(firstByte);
   827→                    bitLen = (modulus.length - i - 1) * 8 + firstByteBits;
   828→                    break;
   829→                }
   830→            }
   831→            cert.publicKeySize = bitLen + ' bits';
   832→        } else if (cert.publicKeyAlgorithm === 'EC') {
   833→            cert.publicKeySize = (pubKeyBits.length * 8 / 2) + ' bits (estimated)';
   834→        } else {
   835→            cert.publicKeySize = 'Unknown';
   836→        }
   837→
   838→        // Extensions (optional, context tag [3])
   839→        cert.extensions = [];
   840→        cert.san = [];
   841→
   842→        while (asn.pos < tbsEnd) {
   843→            if (asn.peek() === 0xa3) {
   844→                asn.readByte();
   845→                const extLen = asn.readLength();
   846→                asn.readSequence();
   847→
   848→                const extEndPos = asn.pos + extLen - 2;
   849→
   850→                while (asn.pos < extEndPos && asn.peek() === 0x30) {
   851→                    try {
   852→                        asn.readSequence();
   853→                        const oid = asn.readOID();
   854→                        const extName = OID_MAP[oid] || oid;
   855→
   856→                        let critical = false;
   857→                        if (asn.peek() === 0x01) {
   858→                            const {value} = asn.readTLV();
   859→                            critical = value[0] !== 0;
   860→                        }
   861→
   862→                        const {value: extValue} = asn.readTLV();
   863→
   864→                        if (oid === '2.5.29.17') { // SAN
   865→                            parseSAN(extValue, cert.san);
   866→                        }
   867→
   868→                        cert.extensions.push({
   869→                            oid,
   870→                            name: extName,
   871→                            critical,
   872→                            value: Array.from(extValue).map(b => b.toString(16).padStart(2, '0')).join('')
   873→                        });
   874→                    } catch (e) {
   875→                        break;
   876→                    }
   877→                }
   878→                break;
   879→            } else {
   880→                try {
   881→                    asn.readTLV();
   882→                } catch (e) {
   883→                    break;
   884→                }
   885→            }
   886→        }
   887→
   888→        // Check self-signed
   889→        cert.selfSigned = JSON.stringify(cert.subject) === JSON.stringify(cert.issuer);
   890→
   891→        // Calculate fingerprints
   892→        cert.derData = der;
   893→
   894→        return cert;
   895→    }
