   897→    function parseDistinguishedName(asn) {
   898→        const dn = {};
   899→        asn.readSequence();
   900→
   901→        while (asn.peek() === 0x31) {
   902→            asn.readByte();
   903→            asn.readLength();
   904→            asn.readSequence();
   905→            const oid = asn.readOID();
   906→            const value = asn.readString();
   907→            const key = OID_MAP[oid] || oid;
   908→            dn[key] = value;
   909→        }
   910→
   911→        return dn;
   912→    }
   913→
   914→    function parseSAN(data, sanList) {
   915→        try {
   916→            const asn = new ASN1(data);
   917→            asn.readSequence();
   918→
   919→            while (asn.pos < data.length) {
   920→                const tag = asn.readByte();
   921→                const len = asn.readLength();
   922→                const value = asn.data.slice(asn.pos, asn.pos + len);
   923→                asn.pos += len;
   924→
   925→                const type = tag & 0x0f;
   926→                const str = new TextDecoder().decode(value);
   927→
   928→                if (type === 2) sanList.push({type: 'DNS', value: str});
   929→                else if (type === 1) sanList.push({type: 'Email', value: str});
   930→                else if (type === 6) sanList.push({type: 'URI', value: str});
   931→                else if (type === 7) {
   932→                    if (value.length === 4) {
   933→                        sanList.push({type: 'IP', value: Array.from(value).join('.')});
   934→                    } else if (value.length === 16) {
   935→                        const ipv6 = [];
   936→                        for (let i = 0; i < 16; i += 2) {
   937→                            ipv6.push(((value[i] << 8) | value[i + 1]).toString(16));
   938→                        }
   939→                        sanList.push({type: 'IP', value: ipv6.join(':')});
   940→                    }
   941→                }
   942→            }
   943→        } catch (e) {
   944→            console.warn('SAN parsing incomplete:', e.message);
   945→            // Add a marker to indicate parsing was incomplete
   946→            if (sanList.length === 0) {
   947→                sanList.push({type: 'Warning', value: 'SAN parsing incomplete'});
   948→            }
   949→        }
   950→    }
