   952→    async function calculateFingerprints(der) {
   953→        const sha256 = await crypto.subtle.digest('SHA-256', der);
   954→        const sha1 = await crypto.subtle.digest('SHA-1', der);
   955→
   956→        const toHex = (buffer) => Array.from(new Uint8Array(buffer))
   957→            .map(b => b.toString(16).padStart(2, '0').toUpperCase())
   958→            .join(':');
   959→
   960→        return {
   961→            sha256: toHex(sha256),
   962→            sha1: toHex(sha1)
   963→        };
   964→    }
