   278→<script>
   279→(function() {
   280→  const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
   281→  const monthNamesCN = ['1月', '2月', '3月', '4月', '5月', '6月', '7月', '8月', '9月', '10月', '11月', '12月'];
   282→  const dayNames = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
   283→
   284→  // Parse URL parameters
   285→  const params = new URLSearchParams(window.location.search);
   286→  const yearParam = params.get('year');
   287→  const layout = params.get('layout');
   288→
   289→  // Determine the year
   290→  let now;
   291→  if (yearParam) {
   292→    now = new Date(yearParam + '-01-01');
   293→    if (isNaN(now.getTime())) {
   294→      now = new Date();
   295→    }
   296→  } else {
   297→    now = new Date();
   298→  }
   299→  const year = now.getFullYear();
   300→
   301→  // Pako compression with base64url encoding
   302→  function compress(str) {
   303→    const bytes = new TextEncoder().encode(str);
   304→    const compressed = pako.deflate(bytes);
   305→    let binary = '';
   306→    for (let i = 0; i < compressed.length; i++) {
   307→      binary += String.fromCharCode(compressed[i]);
   308→    }
   309→    return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
   310→  }
   311→
   312→  function decompress(str) {
   313→    try {
   314→      const base64 = str.replace(/-/g, '+').replace(/_/g, '/');
   315→      const binary = atob(base64);
   316→      const bytes = new Uint8Array(binary.length);
   317→      for (let i = 0; i < binary.length; i++) {
   318→        bytes[i] = binary.charCodeAt(i);
   319→      }
   320→      const decompressed = pako.inflate(bytes);
   321→      return new TextDecoder().decode(decompressed);
   322→    } catch (e) {
   323→      return null;
   324→    }
   325→  }
   326→
   327→  // Events storage (shared across all years)
   328→  const storageKey = 'calendar-events';
   329→  let events = {};
   330→
   331→  // Compact format: "0-1:事项|1-15:另一个"
   332→  function eventsToCompact(obj) {
   333→    return Object.entries(obj).map(([k, v]) => k + ':' + v.replace(/\|/g, '｜').replace(/:/g, '：')).join('|');
   334→  }
   335→
   336→  function compactToEvents(str) {
   337→    const obj = {};
   338→    if (!str) return obj;
   339→    str.split('|').forEach(item => {
   340→      const idx = item.indexOf(':');
   341→      if (idx > 0) {
   342→        const key = item.substring(0, idx);
   343→        const val = item.substring(idx + 1).replace(/｜/g, '|').replace(/：/g, ':');
   344→        obj[key] = val;
   345→      }
   346→    });
   347→    return obj;
   348→  }
   349→
   350→  // Load from URL hash first, then localStorage
   351→  const urlHash = window.location.hash.slice(1);
   352→  if (urlHash) {
   353→    try {
   354→      const decompressed = decompress(urlHash);
   355→      if (decompressed) {
   356→        events = compactToEvents(decompressed);
   357→      }
   358→    } catch (e) {}
   359→  }
   360→  if (Object.keys(events).length === 0) {
   361→    try {
   362→      const stored = localStorage.getItem(storageKey);
   363→      if (stored) {
   364→        events = JSON.parse(stored);
   365→      }
   366→    } catch (e) {}
   367→  }
   368→
   369→  function encodeEvents() {
   370→    return compress(eventsToCompact(events));
   371→  }
   372→
   373→  function getBaseURL() {
   374→    const newParams = new URLSearchParams();
   375→    newParams.set('year', year);
   376→    if (layout) newParams.set('layout', layout);
   377→    return '?' + newParams.toString();
   378→  }
   379→
   380→  function updateURL() {
   381→    let url = getBaseURL();
   382→    if (Object.keys(events).length > 0) {
   383→      url += '#' + encodeEvents();
   384→    }
   385→    history.replaceState(null, '', url);
   386→  }
   387→
   388→  function saveEvents() {
   389→    localStorage.setItem(storageKey, JSON.stringify(events));
   390→    updateURL();
   391→  }
   392→
   393→  function navigateYear(newYear) {
   394→    const newParams = new URLSearchParams();
   395→    newParams.set('year', newYear);
   396→    if (layout) newParams.set('layout', layout);
   397→    let url = '?' + newParams.toString();
   398→    if (Object.keys(events).length > 0) {
   399→      url += '#' + encodeEvents();
   400→    }
   401→    window.location.href = url;
   402→  }
   403→
   404→  function getEventKey(month, day) {
   405→    return month + '-' + day;
   406→  }
   407→
   408→  // Modal elements
   409→  const modalOverlay = document.getElementById('modalOverlay');
   410→  const modalHeader = document.getElementById('modalHeader');
   411→  const eventInput = document.getElementById('eventInput');
   412→  const btnSave = document.getElementById('btnSave');
   413→  const btnCancel = document.getElementById('btnCancel');
   414→  const btnDelete = document.getElementById('btnDelete');
   415→
   416→  let currentCell = null;
   417→  let currentKey = null;
   418→
   419→  function openModal(cell, month, day) {
   420→    currentCell = cell;
   421→    currentKey = getEventKey(month, day);
   422→    modalHeader.textContent = year + '年' + monthNamesCN[month] + day + '日';
   423→    eventInput.value = events[currentKey] || '';
   424→    btnDelete.style.display = events[currentKey] ? 'block' : 'none';
   425→    modalOverlay.classList.add('show');
   426→    eventInput.focus();
   427→  }
   428→
   429→  function closeModal() {
   430→    modalOverlay.classList.remove('show');
   431→    currentCell = null;
   432→    currentKey = null;
   433→  }
   434→
   435→  function updateCellEvent(cell, text) {
   436→    let eventSpan = cell.querySelector('.event-text');
   437→    if (text) {
   438→      if (!eventSpan) {
   439→        eventSpan = document.createElement('span');
   440→        eventSpan.className = 'event-text';
   441→        cell.appendChild(eventSpan);
   442→      }
   443→      eventSpan.textContent = text;
   444→      eventSpan.title = text;
   445→    } else {
   446→      if (eventSpan) {
   447→        eventSpan.remove();
   448→      }
   449→    }
   450→  }
   451→
   452→  function saveEvent() {
   453→    const text = eventInput.value.trim();
   454→    if (text) {
   455→      events[currentKey] = text;
   456→    } else {
   457→      delete events[currentKey];
   458→    }
   459→    updateCellEvent(currentCell, text);
   460→    saveEvents();
   461→    closeModal();
   462→  }
   463→
   464→  function deleteEvent() {
   465→    delete events[currentKey];
   466→    updateCellEvent(currentCell, '');
   467→    saveEvents();
   468→    closeModal();
   469→  }
   470→
   471→  btnSave.addEventListener('click', saveEvent);
   472→  btnCancel.addEventListener('click', closeModal);
   473→  btnDelete.addEventListener('click', deleteEvent);
   474→  modalOverlay.addEventListener('click', function(e) {
   475→    if (e.target === modalOverlay) {
   476→      closeModal();
   477→    }
   478→  });
   479→  document.addEventListener('keydown', function(e) {
   480→    if (modalOverlay.classList.contains('show')) {
   481→      if (e.key === 'Escape') {
   482→        closeModal();
   483→      } else if (e.key === 'Enter' && e.ctrlKey) {
   484→        saveEvent();
   485→      }
   486→    } else {
   487→      if (e.key === 'ArrowLeft') {
   488→        navigateYear(year - 1);
   489→      } else if (e.key === 'ArrowRight') {
   490→        navigateYear(year + 1);
   491→      }
   492→    }
   493→  });
   494→
   495→  // Display current year
   496→  document.getElementById('yearDisplay').textContent = year;
   497→  document.getElementById('prevYear').addEventListener('click', function() { navigateYear(year - 1); });
   498→  document.getElementById('nextYear').addEventListener('click', function() { navigateYear(year + 1); });
   499→
   500→  // Generate month headers
   501→  const headerRow = document.getElementById('monthHeaders');
   502→  for (let i = 0; i < 12; i++) {
   503→    const th = document.createElement('th');
   504→    th.textContent = monthNames[i];
   505→    headerRow.appendChild(th);
   506→  }
   507→
   508→  // Helper: Get days in month
   509→  function getDaysInMonth(year, month) {
   510→    return new Date(year, month + 1, 0).getDate();
   511→  }
   512→
   513→  // Helper: Get ISO weekday (1=Mon, 7=Sun)
   514→  function getISOWeekday(year, month, day) {
   515→    const d = new Date(year, month, day);
   516→    const dow = d.getDay();
   517→    return dow === 0 ? 7 : dow;
   518→  }
   519→
   520→  // Weekend days (ISO weekday: 1=Mon, 7=Sun)
   521→  const weekendDay1 = 6; // Saturday
   522→  const weekendDay2 = 7; // Sunday
   523→
   524→  const tbody = document.getElementById('calendarBody');
   525→
   526→  function createCell(month, dayNum, isWeekend) {
   527→    const td = document.createElement('td');
   528→    if (isWeekend) {
   529→      td.className = 'weekend';
   530→    }
   531→    const key = getEventKey(month, dayNum);
   532→    td.addEventListener('click', function() {
   533→      openModal(td, month, dayNum);
   534→    });
   535→    return { td, key };
   536→  }
   537→
   538→  function addEventText(td, key) {
   539→    if (events[key]) {
   540→      const eventSpan = document.createElement('span');
   541→      eventSpan.className = 'event-text';
   542→      eventSpan.textContent = events[key];
   543→      eventSpan.title = events[key];
   544→      td.appendChild(eventSpan);
   545→    }
   546→  }
   547→
   548→  if (layout === 'aligned-weekdays') {
   549→    // Aligned weekdays layout: 42 rows (6 weeks × 7 days)
   550→    const dates = {};
   551→    for (let m = 0; m < 12; m++) {
   552→      dates[m] = {};
   553→      const firstWeekday = getISOWeekday(year, m, 1);
   554→      const daysInMonth = getDaysInMonth(year, m);
   555→      let day = 1;
   556→      let started = false;
   557→      for (let x = 1; x <= 42; x++) {
   558→        if (!started) {
   559→          if (firstWeekday === x) {
   560→            dates[m][x] = day;
   561→            day++;
   562→            started = true;
   563→          } else {
   564→            dates[m][x] = 0;
   565→          }
   566→        } else {
   567→          if (day > daysInMonth) {
   568→            dates[m][x] = 0;
   569→          } else {
   570→            dates[m][x] = day;
   571→          }
   572→          day++;
   573→        }
   574→      }
   575→    }
   576→
   577→    for (let row = 1; row <= 42; row++) {
   578→      const tr = document.createElement('tr');
   579→      for (let m = 0; m < 12; m++) {
   580→        const dayNum = dates[m][row];
   581→        if (dayNum === 0) {
   582→          const td = document.createElement('td');
   583→          tr.appendChild(td);
   584→        } else {
   585→          const weekday = getISOWeekday(year, m, dayNum);
   586→          const isWeekend = weekday === weekendDay1 || weekday === weekendDay2;
   587→          const { td, key } = createCell(m, dayNum, isWeekend);
   588→          td.appendChild(document.createTextNode(dayNum));
   589→          addEventText(td, key);
   590→          tr.appendChild(td);
   591→        }
   592→      }
   593→      tbody.appendChild(tr);
   594→    }
   595→  } else {
   596→    // Default layout: 31 rows (by day of month)
   597→    for (let day = 1; day <= 31; day++) {
   598→      const tr = document.createElement('tr');
   599→      for (let m = 0; m < 12; m++) {
   600→        const daysInMonth = getDaysInMonth(year, m);
   601→        if (day > daysInMonth) {
   602→          const td = document.createElement('td');
   603→          tr.appendChild(td);
   604→        } else {
   605→          const weekday = getISOWeekday(year, m, day);
   606→          const isWeekend = weekday === weekendDay1 || weekday === weekendDay2;
   607→          const { td, key } = createCell(m, day, isWeekend);
   608→          // Day number
   609→          const dateSpan = document.createElement('span');
   610→          dateSpan.className = 'date';
   611→          dateSpan.textContent = day;
   612→          td.appendChild(dateSpan);
   613→          // Day letter
   614→          td.appendChild(document.createTextNode(' '));
   615→          const daySpan = document.createElement('span');
   616→          daySpan.className = 'day';
   617→          daySpan.textContent = dayNames[weekday - 1].charAt(0);
   618→          td.appendChild(daySpan);
   619→          // Event text
   620→          addEventText(td, key);
   621→          tr.appendChild(td);
   622→        }
   623→      }
   624→      tbody.appendChild(tr);
   625→    }
   626→  }
   627→
   628→  // Update URL with data on initial load
   629→  updateURL();
   630→})();
   631→</script>
