   663→<!-- CodeMirror JS -->
   664→<script src="https://cdn.jsdelivr.net/npm/codemirror@5.65.16/lib/codemirror.min.js"></script>
   665→<script src="https://cdn.jsdelivr.net/npm/codemirror@5.65.16/mode/ruby/ruby.min.js"></script>
   666→<script src="https://cdn.jsdelivr.net/npm/codemirror@5.65.16/addon/edit/matchbrackets.min.js"></script>
   667→<script src="https://cdn.jsdelivr.net/npm/codemirror@5.65.16/addon/edit/closebrackets.min.js"></script>
   668→<script src="https://cdn.jsdelivr.net/npm/codemirror-addon-indent-guide@1.0.1/dist/indent-guide.js"></script>
   669→
   670→<script>
   671→    const inputEl = document.getElementById('input');
   672→    const resultEl = document.getElementById('result');
   673→    const loadingEl = document.getElementById('loading');
   674→    const loadingTextEl = document.getElementById('loadingText');
   675→    const messageEl = document.getElementById('message');
   676→    const statsEl = document.getElementById('stats');
   677→    const formulaTableEl = document.getElementById('formulaTable');
   678→    const dropZone = document.getElementById('dropZone');
   679→    const fileInput = document.getElementById('fileInput');
   680→
   681→    let allFormulas = [];
   682→    let failedFormulas = [];
   683→
   684→    // CodeMirror 配置
   685→    const codeMirrorConfig = {
   686→        mode: "text/x-ruby",
   687→        theme: "material-darker",
   688→        lineNumbers: true,
   689→        lineWrapping: true,
   690→        viewportMargin: Infinity,  // 配合 height:auto 使用，渲染所有行
   691→        matchBrackets: true,
   692→        autoCloseBrackets: true,
   693→        indentUnit: 2,
   694→        tabSize: 2,
   695→        indentGuide: true,
   696→        gutters: ["CodeMirror-linenumbers"]
   697→    };
   698→
   699→    // 初始化 CodeMirror 编辑器
   700→    const editor = CodeMirror.fromTextArea(inputEl, codeMirrorConfig);
   701→
   702→    // 初始化：刷新编辑器
   703→    setTimeout(() => editor.refresh(), 100);
   704→
   705→    // File upload handling
   706→    dropZone.addEventListener('click', () => fileInput.click());
   707→
   708→    fileInput.addEventListener('change', (e) => {
   709→        if (e.target.files.length > 0) {
   710→            handleFile(e.target.files[0]);
   711→        }
   712→    });
   713→
   714→    // Drag and drop
   715→    dropZone.addEventListener('dragover', (e) => {
   716→        e.preventDefault();
   717→        dropZone.classList.add('drag-over');
   718→    });
   719→
   720→    dropZone.addEventListener('dragleave', () => {
   721→        dropZone.classList.remove('drag-over');
   722→    });
   723→
   724→    dropZone.addEventListener('drop', (e) => {
   725→        e.preventDefault();
   726→        dropZone.classList.remove('drag-over');
   727→        if (e.dataTransfer.files.length > 0) {
   728→            handleFile(e.dataTransfer.files[0]);
   729→        }
   730→    });
   731→
   732→    function handleFile(file) {
   733→        const reader = new FileReader();
   734→        reader.onload = (e) => {
   735→            editor.setValue(e.target.result);
   736→            editor.refresh();
   737→            dropZone.classList.add('has-file');
   738→            dropZone.querySelector('.drop-zone-text p').textContent = file.name;
   739→            showMessage(`Loaded ${file.name}`, 'success');
   740→        };
   741→        reader.onerror = () => {
   742→            showMessage('Error reading file', 'error');
   743→        };
   744→        reader.readAsText(file);
   745→    }
   746→
   747→    let brewfileFormulas = [];
   748→    let currentTab = 'all';
   749→    let cy = null;
   750→
   751→    function showMessage(text, type) {
   752→        messageEl.textContent = text;
   753→        messageEl.className = 'message ' + type;
   754→        setTimeout(() => {
   755→            messageEl.className = 'message';
   756→        }, 3000);
   757→    }
   758→
   759→    function escapeHtml(str) {
   760→        if (str === null || str === undefined) return '';
   761→        const s = String(str);
   762→        return s.replace(/[&<>"']/g, c => ({
   763→            '&': '&amp;',
   764→            '<': '&lt;',
   765→            '>': '&gt;',
   766→            '"': '&quot;',
   767→            "'": '&#39;'
   768→        }[c]));
   769→    }
   770→
   771→    function parseBrewfile(content) {
   772→        const formulas = [];
   773→        const lines = content.split('\n');
   774→        for (const line of lines) {
   775→            // Match: brew "formula" or brew 'formula'
   776→            const match = line.match(/^\s*brew\s+["']([^"']+)["']/);
   777→            if (match) {
   778→                formulas.push(match[1]);
   779→            }
   780→        }
   781→        return formulas;
   782→    }
   783→
   784→    async function fetchFormulaInfo(name) {
   785→        try {
   786→            const res = await fetch(`https://formulae.brew.sh/api/formula/${name}.json`);
   787→            if (!res.ok) {
   788→                return {error: true, name, reason: `HTTP ${res.status}`};
   789→            }
   790→            return await res.json();
   791→        } catch (e) {
   792→            return {error: true, name, reason: e.message || 'Network error'};
   793→        }
   794→    }
   795→
   796→    async function analyze() {
   797→        const content = editor.getValue().trim();
   798→        if (!content) {
   799→            showMessage('Please enter a Brewfile', 'error');
   800→            return;
   801→        }
   802→
   803→        const formulas = parseBrewfile(content);
   804→        if (formulas.length === 0) {
   805→            showMessage('No formulas found in Brewfile', 'error');
   806→            return;
   807→        }
   808→
   809→        loadingEl.style.display = 'block';
   810→        resultEl.classList.remove('show');
   811→
   812→        try {
   813→            failedFormulas = [];
   814→            const brewfileSet = new Set(formulas);
   815→            const fetched = new Map(); // name -> formula info (cache)
   816→            const queue = [...formulas]; // formulas to fetch
   817→            const queued = new Set(formulas); // track queued to avoid duplicates
   818→            let fetchCount = 0;
   819→
   820→            // Recursively fetch all dependencies
   821→            while (queue.length > 0) {
   822→                const name = queue.shift();
   823→                queued.delete(name);
   824→
   825→                // Skip if already fetched
   826→                if (fetched.has(name)) continue;
   827→
   828→                fetchCount++;
   829→                loadingTextEl.textContent = `Fetching ${fetchCount}: ${name}...`;
   830→
   831→                const info = await fetchFormulaInfo(name);
   832→                fetched.set(name, info);
   833→
   834→                // If successful, add dependencies to queue
   835→                if (!info.error) {
   836→                    const deps = [
   837→                        ...(info.dependencies || []),
   838→                        ...(info.build_dependencies || [])
   839→                    ];
   840→                    for (const dep of deps) {
   841→                        if (!fetched.has(dep) && !queued.has(dep)) {
   842→                            queue.push(dep);
   843→                            queued.add(dep);
   844→                        }
   845→                    }
   846→                }
   847→
   848→                // Small delay to avoid overwhelming the API
   849→                if (queue.length > 0) {
   850→                    await new Promise(r => setTimeout(r, 50));
   851→                }
   852→            }
   853→
   854→            // Separate successful and failed results
   855→            const allResults = Array.from(fetched.values());
   856→            brewfileFormulas = allResults.filter(r => !r.error && brewfileSet.has(r.name));
   857→            failedFormulas = allResults.filter(r => r.error);
   858→            allFormulas = allResults.filter(r => !r.error);
   859→
   860→            if (brewfileFormulas.length === 0) {
   861→                showMessage('No valid formulas found', 'error');
   862→                loadingEl.style.display = 'none';
   863→                return;
   864→            }
   865→
   866→            renderStats();
   867→            renderGraph();
   868→            renderTable();
   869→
   870→            resultEl.classList.add('show');
   871→            showMessage(`Analyzed ${allFormulas.length} formulas`, 'success');
   872→
   873→        } catch (e) {
   874→            showMessage('Error: ' + e.message, 'error');
   875→        } finally {
   876→            loadingEl.style.display = 'none';
   877→        }
   878→    }
   879→
