  1127→    function showDependencyTree(name) {
  1128→        const formulaMap = new Map(allFormulas.map(f => [f.name, f]));
  1129→        const formula = formulaMap.get(name);
  1130→        if (!formula) return;
  1131→
  1132→        modalTitle.textContent = `${name} - Dependency Tree`;
  1133→
  1134→        function buildTree(formulaName, visited = new Set()) {
  1135→            if (visited.has(formulaName)) {
  1136→                return `<li><span class="node-name node-dep">${escapeHtml(formulaName)}</span> <span style="color:#6b7280;font-size:11px;">(circular)</span></li>`;
  1137→            }
  1138→            visited.add(formulaName);
  1139→
  1140→            const f = formulaMap.get(formulaName);
  1141→            if (!f) {
  1142→                return `<li><span class="node-name node-dep">${escapeHtml(formulaName)}</span> <span style="color:#6b7280;font-size:11px;">(not found)</span></li>`;
  1143→            }
  1144→
  1145→            const deps = f.dependencies || [];
  1146→            const buildDeps = f.build_dependencies || [];
  1147→            const isRoot = formulaName === name;
  1148→
  1149→            let html = `<li><span class="node-name ${isRoot ? 'node-root' : 'node-dep'}">${escapeHtml(formulaName)}</span>`;
  1150→
  1151→            if (deps.length > 0 || buildDeps.length > 0) {
  1152→                html += '<ul>';
  1153→                for (const dep of deps) {
  1154→                    html += buildTree(dep, new Set(visited));
  1155→                }
  1156→                for (const dep of buildDeps) {
  1157→                    if (!deps.includes(dep)) {
  1158→                        const f2 = formulaMap.get(dep);
  1159→                        const innerVisited = new Set(visited);
  1160→                        if (innerVisited.has(dep)) {
  1161→                            html += `<li><span class="node-name node-build">${escapeHtml(dep)}</span> <span style="color:#6b7280;font-size:11px;">(build, circular)</span></li>`;
  1162→                        } else if (!f2) {
  1163→                            html += `<li><span class="node-name node-build">${escapeHtml(dep)}</span> <span style="color:#6b7280;font-size:11px;">(build, not found)</span></li>`;
  1164→                        } else {
  1165→                            innerVisited.add(dep);
  1166→                            const innerDeps = [...(f2.dependencies || []), ...(f2.build_dependencies || [])];
  1167→                            if (innerDeps.length > 0) {
  1168→                                html += `<li><span class="node-name node-build">${escapeHtml(dep)}</span> <span style="color:#6b7280;font-size:11px;">(build)</span>`;
  1169→                                html += '<ul>';
  1170→                                for (const d of f2.dependencies || []) {
  1171→                                    html += buildTree(d, new Set(innerVisited));
  1172→                                }
  1173→                                for (const d of f2.build_dependencies || []) {
  1174→                                    if (!(f2.dependencies || []).includes(d)) {
  1175→                                        html += buildTree(d, new Set(innerVisited));
  1176→                                    }
  1177→                                }
  1178→                                html += '</ul></li>';
  1179→                            } else {
  1180→                                html += `<li><span class="node-name node-build">${escapeHtml(dep)}</span> <span style="color:#6b7280;font-size:11px;">(build)</span></li>`;
  1181→                            }
  1182→                        }
  1183→                    }
  1184→                }
  1185→                html += '</ul>';
  1186→            }
  1187→
  1188→            html += '</li>';
  1189→            return html;
  1190→        }
  1191→
  1192→        depTreeContent.innerHTML = '<ul>' + buildTree(name) + '</ul>';
  1193→        modalOverlay.classList.add('show');
  1194→    }
