   528→<body>
   529→<div class="loading-overlay" id="loading"><div class="loading-spinner"></div></div>
   530→<div class="container">
   531→    <a class="back-link" href="index.html">← Back to Tools</a>
   532→    <h1>Kubernetes Resource Analyzer</h1>
   533→    <p class="subtitle">Analyze Pod, Deployment, StatefulSet, DaemonSet, ReplicaSet, Job, and CronJob specs</p>
   534→
   535→    <div class="main-layout">
   536→        <div class="card">
   537→            <div class="card-header">
   538→                <label>Resource YAML</label>
   539→                <button class="btn-clear-small" onclick="clearAll()">Clear</button>
   540→            </div>
   541→            <textarea id="input" hidden></textarea>
   542→        </div>
   543→
   544→        <div class="card">
   545→            <div class="card-header">
   546→                <label>Analysis Result</label>
   547→                <span id="kindLabel" class="tag tag-info" style="display: none;"></span>
   548→            </div>
   549→            <div id="result" class="analysis-result">
   550→                <div class="empty-state">
   551→                    <p>Paste a resource YAML to analyze</p>
   552→                </div>
   553→            </div>
   554→        </div>
   555→    </div>
   556→</div>
   557→<div class="message" id="message"></div>
   558→
   559→<script defer src="https://cdn.jsdelivr.net/npm/codemirror@5.65.16/lib/codemirror.min.js"></script>
   560→<script defer src="https://cdn.jsdelivr.net/npm/codemirror@5.65.16/mode/yaml/yaml.min.js"></script>
   561→<script defer src="https://cdn.jsdelivr.net/npm/codemirror@5.65.16/addon/edit/matchbrackets.min.js"></script>
   562→<script defer src="https://cdn.jsdelivr.net/npm/codemirror@5.65.16/addon/fold/foldcode.min.js"></script>
   563→<script defer src="https://cdn.jsdelivr.net/npm/codemirror@5.65.16/addon/fold/foldgutter.min.js"></script>
   564→<script defer src="https://cdn.jsdelivr.net/npm/codemirror@5.65.16/addon/fold/indent-fold.min.js"></script>
   565→<script defer src="https://cdn.jsdelivr.net/npm/js-yaml@4.1.0/dist/js-yaml.min.js"></script>
   566→
   567→<script type="module">
   568→    const inputEl = document.getElementById('input');
   569→    const resultEl = document.getElementById('result');
   570→    const messageEl = document.getElementById('message');
   571→
   572→    const baseConfig = {
   573→        theme: "material-darker",
   574→        mode: "yaml",
   575→        lineNumbers: true,
   576→        lineWrapping: true,
   577→        viewportMargin: Infinity,
   578→        maxHighlightLength: Infinity,
   579→        matchBrackets: true,
   580→        indentUnit: 2,
   581→        tabSize: 2,
   582→        foldGutter: {
   583→            rangeFinder: CodeMirror.fold.indent
   584→        },
   585→        gutters: ["CodeMirror-linenumbers", "CodeMirror-foldgutter"]
   586→    };
   587→
   588→    const editor = CodeMirror.fromTextArea(inputEl, baseConfig);
   589→
   590→    requestAnimationFrame(() => {
   591→        editor.refresh();
   592→        document.getElementById('loading').classList.add('hidden');
   593→    });
   594→
   595→    let debounceTimeout;
   596→
   597→    editor.on('change', function(cm, change) {
   598→        clearTimeout(debounceTimeout);
   599→        const isPaste = change.origin === 'paste';
   600→        const delay = isPaste ? 0 : 400;
   601→        debounceTimeout = setTimeout(analyze, delay);
   602→    });
   603→
   604→    function showMessage(text, type) {
   605→        messageEl.textContent = text;
   606→        messageEl.className = 'message ' + type;
   607→        setTimeout(() => {
   608→            messageEl.className = 'message';
   609→        }, 3000);
   610→    }
   611→
   612→    function analyze() {
   613→        const text = editor.getValue().trim();
   614→        if (!text) {
   615→            document.getElementById('kindLabel').style.display = 'none';
   616→            resultEl.innerHTML = `
   617→                <div class="empty-state">
   618→                    <p>Paste a resource YAML to analyze</p>
   619→                </div>
   620→            `;
   621→            return;
   622→        }
   623→
   624→        let spec;
   625→        try {
   626→            spec = jsyaml.load(text);
   627→        } catch (e) {
   628→            showMessage('Invalid YAML: ' + e.message, 'error');
   629→            return;
   630→        }
   631→
   632→        if (!spec || typeof spec !== 'object') {
   633→            showMessage('Invalid YAML structure', 'error');
   634→            return;
   635→        }
   636→
   637→        const pod = normalizePodSpec(spec);
   638→        if (!pod) {
   639→            showMessage('Not a valid Pod, Deployment, StatefulSet, DaemonSet, ReplicaSet, Job, or CronJob', 'error');
   640→            return;
   641→        }
   642→
   643→        renderAnalysis(pod, spec);
   644→    }
   645→
   646→    function normalizePodSpec(spec) {
   647→        const kind = spec.kind || '';
   648→        
   649→        if (kind === 'Pod') {
   650→            return {
   651→                metadata: spec.metadata || {},
   652→                spec: spec.spec || {},
   653→                kind: 'Pod'
   654→            };
   655→        }
   656→        
   657→        if (['Deployment', 'StatefulSet', 'DaemonSet', 'ReplicaSet'].includes(kind)) {
   658→            return {
   659→                metadata: spec.spec?.template?.metadata || {},
   660→                spec: spec.spec?.template?.spec || {},
   661→                kind: kind,
   662→                parentMetadata: spec.metadata || {}
   663→            };
   664→        }
   665→        
   666→        if (kind === 'Job') {
   667→            return {
   668→                metadata: spec.spec?.template?.metadata || {},
   669→                spec: spec.spec?.template?.spec || {},
   670→                kind: kind,
   671→                parentMetadata: spec.metadata || {}
   672→            };
   673→        }
   674→        
   675→        if (kind === 'CronJob') {
   676→            return {
   677→                metadata: spec.spec?.jobTemplate?.spec?.template?.metadata || {},
   678→                spec: spec.spec?.jobTemplate?.spec?.template?.spec || {},
   679→                kind: kind,
   680→                parentMetadata: spec.metadata || {}
   681→            };
   682→        }
   683→
   684→        if (spec.spec?.containers) {
   685→            return {
   686→                metadata: spec.metadata || {},
   687→                spec: spec.spec,
   688→                kind: 'Pod'
   689→            };
   690→        }
   691→
   692→        return null;
   693→    }
   694→
   695→    function renderAnalysis(pod, originalSpec) {
   696→        // Update Kind label
   697→        const kindLabel = document.getElementById('kindLabel');
   698→        kindLabel.textContent = pod.kind;
   699→        kindLabel.style.display = 'inline-block';
   700→
   701→        const metadata = pod.metadata || {};
   702→        const spec = pod.spec || {};
   703→        const containers = spec.containers || [];
   704→        const initContainers = spec.initContainers || [];
   705→        const volumes = spec.volumes || [];
   706→
   707→        let html = '';
   708→
   709→        html += renderMetadataSection(metadata, pod, originalSpec);
   710→        html += renderContainersSection(containers, 'Containers', spec);
   711→        html += renderContainersSection(initContainers, 'Init Containers', spec);
   712→        html += renderVolumesSection(volumes, containers.concat(initContainers));
   713→        html += renderSecuritySection(spec);
   714→        html += renderSchedulingSection(spec);
   715→
   716→        resultEl.innerHTML = html;
   717→    }
   718→
   719→    function renderMetadataSection(metadata, pod, originalSpec) {
   720→        const labels = metadata.labels || {};
   721→        const annotations = metadata.annotations || {};
   722→        const parentMeta = pod.parentMetadata || {};
   723→
   724→        let html = `<div class="section">
   725→            <div class="section-title">Metadata</div>
   726→            <div class="info-grid">`;
   727→        
   728→        if (pod.kind !== 'Pod' && parentMeta.name) {
   729→            html += `<span class="info-label">${pod.kind} Name</span>
   730→                     <span class="info-value mono">${parentMeta.name}</span>`;
   731→        }
   732→
   733→        if (metadata.name) {
   734→            html += `<span class="info-label">Name</span>
   735→                     <span class="info-value mono">${metadata.name}</span>`;
   736→        }
   737→        
   738→        const ns = metadata.namespace || parentMeta.namespace || 'default';
   739→        html += `<span class="info-label">Namespace</span>
   740→                 <span class="info-value mono">${ns}</span>`;
   741→        
   742→        if (originalSpec.apiVersion) {
   743→            html += `<span class="info-label">API Version</span>
   744→                     <span class="info-value mono">${originalSpec.apiVersion}</span>`;
   745→        }
   746→
   747→        if (Object.keys(labels).length > 0) {
   748→            html += `<span class="info-label">Labels</span>
   749→                <div class="label-tags">`;
   750→            for (const [k, v] of Object.entries(labels)) {
   751→                html += `<span class="tag tag-info">${escapeHtml(k)}=${escapeHtml(v)}</span>`;
   752→            }
   753→            html += `</div>`;
   754→        }
   755→
   756→        if (Object.keys(annotations).length > 0) {
   757→            html += `<span class="info-label">Annotations</span>
   758→                <div class="label-tags">`;
   759→            for (const [k, v] of Object.entries(annotations)) {
   760→                html += `<span class="tag tag-success">${escapeHtml(k)}=${escapeHtml(v)}</span>`;
   761→            }
   762→            html += `</div>`;
   763→        }
   764→
   765→        html += `</div></div>`;
   766→        return html;
   767→    }
   768→
   769→    function renderContainersSection(containers, title, podSpec) {
   770→        if (containers.length === 0) return '';
   771→        const isMainContainer = title === 'Containers';
   772→
   773→        let html = `<div class="section">
   774→            <div class="section-title">${title} (${containers.length})</div>`;
   775→
   776→        containers.forEach(c => {
   777→            const sc = c.securityContext || {};
   778→            const image = c.image || '';
   779→            
   780→            html += `<div class="container-card">
   781→                <div class="container-name">${escapeHtml(c.name)}</div>
   782→                <div class="info-grid">
   783→                    <span class="info-label">Image</span>
   784→                    <span class="info-value mono">${escapeHtml(image || 'N/A')}`;
   785→            
   786→            // Image tag warning inline
   787→            if (image.endsWith(':latest')) {
   788→                html += ` <span class="inline-warning">:latest</span>`;
   789→            } else if (image && !image.includes(':') && !image.includes('@')) {
   790→                html += ` <span class="inline-warning">no tag</span>`;
   791→            }
   792→            html += `</span>`;
   793→            
   794→            if (c.command) {
   795→                html += `<span class="info-label">Command</span>
   796→                         <span class="info-value mono">${escapeHtml(JSON.stringify(c.command))}</span>`;
   797→            }
   798→            if (c.args) {
   799→                html += `<span class="info-label">Args</span>
   800→                         <span class="info-value mono">${escapeHtml(JSON.stringify(c.args))}</span>`;
   801→            }
   802→            if (c.ports && c.ports.length > 0) {
   803→                const ports = c.ports.map(p => `${p.containerPort}/${p.protocol || 'TCP'}`).join(', ');
   804→                html += `<span class="info-label">Ports</span>
   805→                         <span class="info-value mono">${escapeHtml(ports)}</span>`;
   806→            }
   807→
   808→            // Resources
   809→            html += renderResources(c.resources);
   810→
   811→            // Security Context
   812→            html += renderContainerSecurity(sc);
   813→
   814→            if (c.env && c.env.length > 0) {
   815→                html += renderEnvVars(c.env);
   816→            }
   817→
   818→            if (c.envFrom && c.envFrom.length > 0) {
   819→                html += renderEnvFrom(c.envFrom);
   820→            }
   821→
   822→            // Probes (only for main containers)
   823→            if (isMainContainer) {
   824→                html += renderProbes(c);
   825→            }
   826→
   827→            html += `</div>`;
   828→
   829→            html += `</div>`;
   830→        });
   831→
   832→        html += `</div>`;
   833→        return html;
   834→    }
   835→
   836→    function renderContainerSecurity(sc) {
   837→        const items = [];
   838→        
   839→        if (sc.privileged === true) {
   840→            items.push({ label: 'Privileged', value: 'true', type: 'error' });
   841→        }
   842→        if (sc.runAsUser !== undefined) {
   843→            const type = sc.runAsUser === 0 ? 'error' : 'success';
   844→            items.push({ label: 'runAsUser', value: sc.runAsUser, type });
   845→        }
   846→        if (sc.runAsNonRoot !== undefined) {
   847→            items.push({ label: 'runAsNonRoot', value: sc.runAsNonRoot, type: sc.runAsNonRoot ? 'success' : 'warning' });
   848→        }
   849→        if (sc.readOnlyRootFilesystem !== undefined) {
   850→            items.push({ label: 'readOnlyRootFilesystem', value: sc.readOnlyRootFilesystem, type: sc.readOnlyRootFilesystem ? 'success' : 'info' });
   851→        }
   852→        if (sc.allowPrivilegeEscalation !== undefined) {
   853→            items.push({ label: 'allowPrivilegeEscalation', value: sc.allowPrivilegeEscalation, type: sc.allowPrivilegeEscalation ? 'warning' : 'success' });
   854→        }
   855→        if (sc.capabilities?.drop?.length > 0) {
   856→            items.push({ label: 'Drop capabilities', value: sc.capabilities.drop.join(', '), type: 'success' });
   857→        }
   858→        if (sc.capabilities?.add?.length > 0) {
   859→            items.push({ label: 'Add capabilities', value: sc.capabilities.add.join(', '), type: 'warning' });
   860→        }
   861→
