function tryParseJSON(text) {
    let firstError;
    try {
        const parsed = JSON.parse(text);
        // Detect double-encoded JSON: a string value that itself is a JSON object/array.
        if (typeof parsed === 'string') {
            try {
                const inner = JSON.parse(parsed);
                if (typeof inner === 'object' && inner !== null) {
                    return inner;
                }
            } catch (_) {}
        }
        return parsed;
    } catch (e) {
        firstError = e;
    }

    // Try unescaping key/value quotes only (common when copying from logs/code).
    // Avoid touching \\\" inside string content.
    if (!text.includes('\\"')) {
        throw firstError;
    }

    const unescaped = text.replace(/(?<!\\)\\"/g, '"');
    if (unescaped === text) {
        throw firstError;
    }

    try {
        return JSON.parse(unescaped);
    } catch (_) {
        throw firstError;
    }
}

function processJSON(text, processor, successMessage) {
    try {
        const parsed = tryParseJSON(text);
        const result = processor(parsed);
        editorOutput.setValue(result);
        editorOutput.clearHistory();
        editorOutput.refresh();
        showMessage(successMessage, 'success');
        return true;
    } catch (e) {
        showMessage('Invalid JSON: ' + e.message, 'error');
        return false;
    }
}

